window.GITA=window.GITA||{};GITA.capitulos=GITA.capitulos||{};GITA.capitulos[4]={"numero": 4, "titulo": "El yoga del conocimiento y la renuncia a la acción", "versos": [{"n": 1, "hablante": "krsna", "sa": ["श्रीभगवानुवाच ।", "इमं विवस्वते योगं प्रोक्तवानहमव्ययम् ।", "विवस्वान्मनवे प्राह मनुरिक्ष्वाकवेऽब्रवीत् ॥१॥"], "iast": ["śrī-bhagavān uvāca", "imaṃ vivasvate yogaṃ proktavān aham avyayam", "vivasvān manave prāha manur ikṣvākave 'bravīt"], "rojas": [1, 2], "t": "<span class=\"vt-parte voz-krsna\">Este <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a> imperecedero se lo enseñé yo a <a class=\"t\" href=\"glosario.html#vivasvat\" data-t=\"vivasvat\">Vivasvat</a>; Vivasvat se lo transmitió a <a class=\"t\" href=\"glosario.html#manu\" data-t=\"manu\">Manu</a>, y Manu se lo dijo a <a class=\"t\" href=\"glosario.html#iksvaku\" data-t=\"iksvaku\">Ikṣvāku</a>.</span>", "palabras": [{"iast": "śrī-bhagavān", "sa": "श्रीभगवान्", "gram": "nom. sg. m. comp.", "es": "el glorioso Señor", "ref": "bhagavan", "analisis": "śrī (gloria) + bhagavat (el Señor)"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "imam", "sa": "इमम्", "gram": "ac. sg. m. pron.", "es": "este"}, {"iast": "vivasvate", "sa": "विवस्वते", "gram": "dat. sg. m.", "es": "a Vivasvat", "ref": "vivasvat", "analisis": "vivasvat, «el resplandeciente»: el Sol"}, {"iast": "yogam", "sa": "योगम्", "gram": "ac. sg. m.", "es": "yoga", "ref": "yoga"}, {"iast": "proktavān", "sa": "प्रोक्तवान्", "gram": "nom. sg. m. part.", "es": "enseñé (lit. «habiendo enseñado»)", "analisis": "pra-√vac (proclamar, enseñar); participio pasado activo en -vat"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "avyayam", "sa": "अव्ययम्", "gram": "ac. sg. m. adj.", "es": "imperecedero", "analisis": "a (no) + vyaya (gasto, pérdida)"}, {"iast": "vivasvān", "sa": "विवस्वान्", "gram": "nom. sg. m.", "es": "Vivasvat", "ref": "vivasvat"}, {"iast": "manave", "sa": "मनवे", "gram": "dat. sg. m.", "es": "a Manu", "ref": "manu"}, {"iast": "prāha", "sa": "प्राह", "gram": "3 sg. pf. act.", "es": "transmitió, dijo", "analisis": "pra-√ah (decir)"}, {"iast": "manuḥ", "sa": "मनुः", "gram": "nom. sg. m.", "es": "Manu", "ref": "manu"}, {"iast": "ikṣvākave", "sa": "इक्ष्वाकवे", "gram": "dat. sg. m.", "es": "a Ikṣvāku", "ref": "iksvaku"}, {"iast": "abravīt", "sa": "अब्रवीत्", "gram": "3 sg. impf. act.", "es": "dijo", "analisis": "√brū (decir)"}], "nota": "<p>Comienza la exposición del capítulo con una genealogía. <a class=\"t\" href=\"glosario.html#vivasvat\" data-t=\"vivasvat\">Vivasvat</a> es el Sol; <a class=\"t\" href=\"glosario.html#manu\" data-t=\"manu\">Manu</a>, su hijo, el padre de la humanidad y legislador primordial; <a class=\"t\" href=\"glosario.html#iksvaku\" data-t=\"iksvaku\">Ikṣvāku</a>, hijo de Manu, el primer rey de Ayodhyā y fundador de la dinastía solar, a la que pertenecerá Rāma. Kṛṣṇa presenta así su enseñanza no como una doctrina nueva, sino como la más antigua de todas, transmitida desde el comienzo de maestro a discípulo.</p><p>El verbo <em>proktavān</em> («habiendo enseñado») es un participio usado como verbo principal: «yo lo enseñé». Que Kṛṣṇa, un hombre de la generación de Arjuna, diga haberlo enseñado al Sol provoca la pregunta de <a class=\"vref\" href=\"capitulo-04.html#v4\" data-v=\"4.4\">4.4</a>.</p>", "interp": [{"titulo": "Una cadena solar", "html": "<p>La cadena Sol → Manu → Ikṣvāku es la de la dinastía solar (<em>sūrya-vaṃśa</em>), la de los reyes de Ayodhyā y de Rāma, héroe del <a class=\"t\" href=\"glosario.html#ramayana\" data-t=\"ramayana\">Rāmāyaṇa</a>. Kṛṣṇa, que pertenece a la dinastía lunar a través de los <a class=\"t\" href=\"glosario.html#yadavas\" data-t=\"yadavas\">Yādavas</a>, sitúa su enseñanza en la otra gran estirpe real de la épica: el yoga que expone es un saber de reyes, transmitido de padres a hijos, más que un saber de sacerdotes.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "Una novedad presentada como antigua", "html": "<p>Los historiadores de las religiones observan que atribuir una enseñanza a un origen primordial es un recurso habitual para legitimar doctrinas nuevas. La Gītā propone una síntesis que no estaba en los Vedas —la acción sin apego, la devoción a un Dios personal— y la presenta como el saber más antiguo, interrumpido por el tiempo y ahora restablecido (<a class=\"vref\" href=\"capitulo-04.html#v2\" data-v=\"4.2\">4.2</a>–<a class=\"vref\" href=\"capitulo-04.html#v3\" data-v=\"4.3\">4.3</a>).</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 2, "hablante": "krsna", "sa": ["एवं परम्पराप्राप्तमिमं राजर्षयो विदुः ।", "स कालेनेह महता योगो नष्टः परन्तप ॥२॥"], "iast": ["evaṃ paramparā-prāptam imaṃ rājarṣayo viduḥ", "sa kāleneha mahatā yogo naṣṭaḥ parantapa"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Así, recibido de uno en otro, lo conocieron los <a class=\"t\" href=\"glosario.html#rajarsi\" data-t=\"rajarsi\">reyes sabios</a>. Pero con el largo paso del tiempo, ese <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a> se perdió aquí, oh <a class=\"t\" href=\"glosario.html#parantapa\" data-t=\"parantapa\">Parantapa</a>.</span>", "palabras": [{"iast": "evam", "sa": "एवम्", "gram": "ind.", "es": "así"}, {"iast": "paramparā-prāptam", "sa": "परम्पराप्राप्तम्", "gram": "ac. sg. m. comp.", "es": "recibido de uno en otro", "analisis": "paramparā (sucesión, uno tras otro) + prāpta (recibido; ppp de pra-√āp, alcanzar)"}, {"iast": "imam", "sa": "इमम्", "gram": "ac. sg. m. pron.", "es": "este"}, {"iast": "rājarṣayaḥ", "sa": "राजर्षयः", "gram": "nom. pl. m.", "es": "los reyes sabios", "ref": "rajarsi", "analisis": "rājan (rey) + ṛṣi (vidente, sabio)"}, {"iast": "viduḥ", "sa": "विदुः", "gram": "3 pl. pf. act.", "es": "conocieron", "analisis": "√vid (saber); el perfecto tiene valor de presente: «conocen»"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "ese"}, {"iast": "kālena", "sa": "कालेन", "gram": "instr. sg. m.", "es": "con el tiempo"}, {"iast": "iha", "sa": "इह", "gram": "ind.", "es": "aquí, en este mundo"}, {"iast": "mahatā", "sa": "महता", "gram": "instr. sg. m. adj.", "es": "largo, grande"}, {"iast": "yogaḥ", "sa": "योगः", "gram": "nom. sg. m.", "es": "yoga", "ref": "yoga"}, {"iast": "naṣṭaḥ", "sa": "नष्टः", "gram": "nom. sg. m. ppp", "es": "se perdió", "analisis": "√naś (perderse, desaparecer)"}, {"iast": "parantapa", "sa": "परन्तप", "gram": "voc. sg. m.", "es": "oh Parantapa", "ref": "parantapa"}], "nota": "<p><em>Paramparā</em>, «uno tras otro», es la transmisión ininterrumpida de maestro a discípulo, y la palabra que la tradición india usa para el linaje de una enseñanza. Los que la recibieron fueron <a class=\"t\" href=\"glosario.html#rajarsi\" data-t=\"rajarsi\">reyes sabios</a> (<em>rājarṣi</em>): gobernantes que eran a la vez videntes, como <a class=\"t\" href=\"glosario.html#janaka\" data-t=\"janaka\">Janaka</a> (<a class=\"vref\" href=\"capitulo-03.html#v20\" data-v=\"3.20\">3.20</a>). El yoga de la acción es, en su origen, un saber para quienes actúan en el mundo.</p><p>«Se perdió» no significa que desapareciera del todo, sino que la cadena se rompió: hacía falta enseñarlo de nuevo.</p>", "interp": [{"titulo": "Por qué se perdió", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> explica que el yoga se perdió al llegar a manos de hombres débiles, sin dominio de sus sentidos (<em>durbalān ajitendriyān</em>), y que Kṛṣṇa, al ver que el mundo quedaba entregado a fines que no conducen a la liberación, vuelve a enseñarlo a Arjuna.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Una enseñanza para quienes actúan", "html": "<p>Que los primeros depositarios fueran reyes concuerda con todo el capítulo 3: la Gītā no se dirige a quien ha dejado el mundo, sino a quien tiene que actuar en él y gobernar. Arjuna, guerrero y príncipe, es el destinatario natural de un saber de <em>rājarṣis</em>.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 3, "hablante": "krsna", "sa": ["स एवायं मया तेऽद्य योगः प्रोक्तः पुरातनः ।", "भक्तोऽसि मे सखा चेति रहस्यं ह्येतदुत्तमम् ॥३॥"], "iast": ["sa evāyaṃ mayā te 'dya yogaḥ proktaḥ purātanaḥ", "bhakto 'si me sakhā ceti rahasyaṃ hy etad uttamam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Ese mismo yoga antiguo es el que hoy te he enseñado, porque eres mi <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">devoto</a> y mi amigo: es éste, en efecto, el secreto supremo.</span>", "palabras": [{"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "ese"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "mismo"}, {"iast": "ayam", "sa": "अयम्", "gram": "nom. sg. m. pron.", "es": "este"}, {"iast": "mayā", "sa": "मया", "gram": "instr. sg. pron.", "es": "por mí"}, {"iast": "te", "sa": "ते", "gram": "dat. sg. pron.", "es": "a ti"}, {"iast": "adya", "sa": "अद्य", "gram": "ind.", "es": "hoy"}, {"iast": "yogaḥ", "sa": "योगः", "gram": "nom. sg. m.", "es": "yoga", "ref": "yoga"}, {"iast": "proktaḥ", "sa": "प्रोक्तः", "gram": "nom. sg. m. ppp", "es": "ha sido enseñado", "analisis": "pra-√vac (enseñar)"}, {"iast": "purātanaḥ", "sa": "पुरातनः", "gram": "nom. sg. m. adj.", "es": "antiguo", "analisis": "de purā (antes)"}, {"iast": "bhaktaḥ", "sa": "भक्तः", "gram": "nom. sg. m.", "es": "devoto", "ref": "bhakti", "analisis": "ppp de √bhaj (participar, adorar): «el que participa, el devoto»"}, {"iast": "asi", "sa": "असि", "gram": "2 sg. pres. act.", "es": "eres", "analisis": "√as (ser)"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "mi"}, {"iast": "sakhā", "sa": "सखा", "gram": "nom. sg. m.", "es": "amigo"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "iti", "sa": "इति", "gram": "ind.", "es": "por eso (lit. «así»)", "analisis": "aquí iti indica la razón"}, {"iast": "rahasyam", "sa": "रहस्यम्", "gram": "nom. sg. n.", "es": "secreto", "analisis": "de rahas (lugar apartado, soledad)"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues"}, {"iast": "etat", "sa": "एतत्", "gram": "nom. sg. n. pron.", "es": "esto"}, {"iast": "uttamam", "sa": "उत्तमम्", "gram": "nom. sg. n. adj.", "es": "supremo"}], "nota": "<p>Kṛṣṇa da la razón de que Arjuna reciba la enseñanza: no su linaje ni su saber, sino una relación personal, «eres mi devoto y mi amigo». Es la primera vez que aparece en la Gītā la palabra <em>bhakta</em>, «devoto», que irá ganando peso hasta el capítulo 12.</p><p><em>Rahasya</em> es lo que se dice en un lugar apartado, a solas: el secreto o misterio. La Gītā volverá a calificar su enseñanza de secreta en <a class=\"vref\" href=\"capitulo-09.html#v1\" data-v=\"9.1\">9.1</a>–<a class=\"vref\" href=\"capitulo-09.html#v2\" data-v=\"9.2\">9.2</a> y, al final, en <a class=\"vref\" href=\"capitulo-18.html#v63\" data-v=\"18.63\">18.63</a>–<a class=\"vref\" href=\"capitulo-18.html#v64\" data-v=\"18.64\">18.64</a>.</p>", "interp": [{"titulo": "Devoto y amigo", "html": "<p>Las lecturas devocionales subrayan que la condición para recibir la enseñanza es el amor y la confianza, no la erudición. Arjuna es a la vez devoto y amigo: la Gītā une la reverencia ante Dios y la familiaridad con él, dos actitudes que la tradición posterior distinguirá como formas distintas de devoción.</p>", "trad": "devocional", "tradNombre": "Lecturas devocionales"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 4, "hablante": "arjuna", "sa": ["अर्जुन उवाच ।", "अपरं भवतो जन्म परं जन्म विवस्वतः ।", "कथमेतद्विजानीयां त्वमादौ प्रोक्तवानिति ॥४॥"], "iast": ["arjuna uvāca", "aparaṃ bhavato janma paraṃ janma vivasvataḥ", "katham etad vijānīyāṃ tvam ādau proktavān iti"], "rojas": [], "t": "<span class=\"vt-parte\">Tu nacimiento es posterior; anterior, el nacimiento de <a class=\"t\" href=\"glosario.html#vivasvat\" data-t=\"vivasvat\">Vivasvat</a>. ¿Cómo he de entender que tú se lo enseñaste al principio?</span>", "palabras": [{"iast": "arjunaḥ", "sa": "अर्जुनः", "gram": "nom. sg. m.", "es": "Arjuna", "ref": "arjuna"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "aparam", "sa": "अपरम्", "gram": "nom. sg. n. adj.", "es": "posterior"}, {"iast": "bhavataḥ", "sa": "भवतः", "gram": "gen. sg. m. pron.", "es": "tuyo", "analisis": "bhavat, pronombre de cortesía («vuestra merced»)"}, {"iast": "janma", "sa": "जन्म", "gram": "nom. sg. n.", "es": "nacimiento", "analisis": "√jan (nacer)"}, {"iast": "param", "sa": "परम्", "gram": "nom. sg. n. adj.", "es": "anterior"}, {"iast": "janma", "sa": "जन्म", "gram": "nom. sg. n.", "es": "nacimiento"}, {"iast": "vivasvataḥ", "sa": "विवस्वतः", "gram": "gen. sg. m.", "es": "de Vivasvat", "ref": "vivasvat"}, {"iast": "katham", "sa": "कथम्", "gram": "ind.", "es": "¿cómo?"}, {"iast": "etat", "sa": "एतत्", "gram": "ac. sg. n. pron.", "es": "esto"}, {"iast": "vijānīyām", "sa": "विजानीयाम्", "gram": "1 sg. opt. act.", "es": "he de entender", "analisis": "vi-√jñā (comprender)"}, {"iast": "tvam", "sa": "त्वम्", "gram": "nom. sg. pron.", "es": "tú"}, {"iast": "ādau", "sa": "आदौ", "gram": "loc. sg. m.", "es": "al principio"}, {"iast": "proktavān", "sa": "प्रोक्तवान्", "gram": "nom. sg. m. part.", "es": "enseñaste"}, {"iast": "iti", "sa": "इति", "gram": "ind.", "es": "(cierra la cita)"}], "nota": "<p>La objeción es razonable: Arjuna conoce a Kṛṣṇa como su primo, nacido pocos años antes que él, y no puede entender que haya enseñado nada al Sol al comienzo de los tiempos. Usa el pronombre de cortesía <em>bhavat</em>, el mismo con que se habla a un superior. Su pregunta abre la doctrina del nacimiento divino de los versos siguientes.</p>", "interp": [{"titulo": "La pregunta que revela a Kṛṣṇa", "html": "<p>Hasta aquí Arjuna ha tratado a Kṛṣṇa como consejero y amigo. Esta pregunta, que nace de tomar sus palabras al pie de la letra, obliga a Kṛṣṇa a decir quién es: el capítulo 4 es el primero en que habla abiertamente de sí mismo como Dios, y el camino conduce a la visión del capítulo 11.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 5, "hablante": "krsna", "sa": ["श्रीभगवानुवाच ।", "बहूनि मे व्यतीतानि जन्मानि तव चार्जुन ।", "तान्यहं वेद सर्वाणि न त्वं वेत्थ परन्तप ॥५॥"], "iast": ["śrī-bhagavān uvāca", "bahūni me vyatītāni janmāni tava cārjuna", "tāny ahaṃ veda sarvāṇi na tvaṃ vettha parantapa"], "rojas": [1, 2], "t": "<span class=\"vt-parte voz-krsna\">Muchos son los nacimientos que han pasado, míos y tuyos, oh <a class=\"t\" href=\"glosario.html#arjuna\" data-t=\"arjuna\">Arjuna</a>. Yo los conozco todos; tú no los conoces, oh <a class=\"t\" href=\"glosario.html#parantapa\" data-t=\"parantapa\">Parantapa</a>.</span>", "palabras": [{"iast": "śrī-bhagavān", "sa": "श्रीभगवान्", "gram": "nom. sg. m. comp.", "es": "el glorioso Señor", "ref": "bhagavan", "analisis": "śrī (gloria) + bhagavat (el Señor)"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "bahūni", "sa": "बहूनि", "gram": "nom. pl. n. adj.", "es": "muchos"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "míos"}, {"iast": "vyatītāni", "sa": "व्यतीतानि", "gram": "nom. pl. n. ppp", "es": "han pasado", "analisis": "vi-ati-√i (pasar más allá)"}, {"iast": "janmāni", "sa": "जन्मानि", "gram": "nom. pl. n.", "es": "nacimientos"}, {"iast": "tava", "sa": "तव", "gram": "gen. sg. pron.", "es": "tuyos"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "arjuna", "sa": "अर्जुन", "gram": "voc. sg. m.", "es": "oh Arjuna", "ref": "arjuna"}, {"iast": "tāni", "sa": "तानि", "gram": "ac. pl. n. pron.", "es": "esos"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "veda", "sa": "वेद", "gram": "1 sg. pf. act.", "es": "conozco", "analisis": "√vid (saber); perfecto con valor de presente"}, {"iast": "sarvāṇi", "sa": "सर्वाणि", "gram": "ac. pl. n. adj.", "es": "todos"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "tvam", "sa": "त्वम्", "gram": "nom. sg. pron.", "es": "tú"}, {"iast": "vettha", "sa": "वेत्थ", "gram": "2 sg. pf. act.", "es": "conoces", "analisis": "√vid (saber)"}, {"iast": "parantapa", "sa": "परन्तप", "gram": "voc. sg. m.", "es": "oh Parantapa", "ref": "parantapa"}], "nota": "<p>Kṛṣṇa no niega haber nacido: afirma que ha nacido muchas veces, como Arjuna. La diferencia no está en el número de nacimientos, sino en el conocimiento: él los recuerda todos; Arjuna, ninguno. El verso prolonga lo dicho en <a class=\"vref\" href=\"capitulo-02.html#v12\" data-v=\"2.12\">2.12</a>: ni Kṛṣṇa ni Arjuna empezaron a existir con este cuerpo.</p>", "interp": [{"titulo": "Memoria y olvido", "html": "<p>Los comentaristas advaitas explican que Kṛṣṇa conoce sus nacimientos porque su conocimiento no está velado, mientras que el de Arjuna, como el de todo ser encarnado, queda oscurecido: por el mérito y el demérito de sus actos, según <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>; por la ignorancia, según <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>. <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, en cambio, sólo ve aquí la prueba de que los nacimientos de Kṛṣṇa son reales, como los de Arjuna. El verso prepara la distinción del siguiente: los nacimientos de Arjuna son forzados; los de Kṛṣṇa, libres.</p>", "trad": "vedanta", "tradNombre": "Vedānta clásico"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "descensos-de-krsna"}, {"n": 6, "hablante": "krsna", "sa": ["अजोऽपि सन्नव्ययात्मा भूतानामीश्वरोऽपि सन् ।", "प्रकृतिं स्वामधिष्ठाय सम्भवाम्यात्ममायया ॥६॥"], "iast": ["ajo 'pi sann avyayātmā bhūtānām īśvaro 'pi san", "prakṛtiṃ svām adhiṣṭhāya sambhavāmy ātma-māyayā"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Aunque soy no nacido y de naturaleza imperecedera, aunque soy el Señor de los seres, apoyándome en mi propia <a class=\"t\" href=\"glosario.html#prakrti\" data-t=\"prakrti\">naturaleza</a> me manifiesto por mi propia <a class=\"t\" href=\"glosario.html#maya\" data-t=\"maya\">māyā</a>.</span>", "palabras": [{"iast": "ajaḥ", "sa": "अजः", "gram": "nom. sg. m. adj.", "es": "no nacido", "analisis": "a (no) + ja (nacido, de √jan)"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "aunque"}, {"iast": "san", "sa": "सन्", "gram": "nom. sg. m. part.", "es": "siendo", "analisis": "participio presente de √as (ser)"}, {"iast": "avyaya-ātmā", "sa": "अव्ययात्मा", "gram": "nom. sg. m. comp.", "es": "de naturaleza imperecedera", "analisis": "avyaya (imperecedero) + ātman (naturaleza, ser propio)"}, {"iast": "bhūtānām", "sa": "भूतानाम्", "gram": "gen. pl. n.", "es": "de los seres"}, {"iast": "īśvaraḥ", "sa": "ईश्वरः", "gram": "nom. sg. m.", "es": "el Señor", "analisis": "√īś (poseer, gobernar)"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "aunque"}, {"iast": "san", "sa": "सन्", "gram": "nom. sg. m. part.", "es": "siendo"}, {"iast": "prakṛtim", "sa": "प्रकृतिम्", "gram": "ac. sg. f.", "es": "naturaleza", "ref": "prakrti"}, {"iast": "svām", "sa": "स्वाम्", "gram": "ac. sg. f. adj.", "es": "propia"}, {"iast": "adhiṣṭhāya", "sa": "अधिष्ठाय", "gram": "abs.", "es": "apoyándome en, rigiendo", "analisis": "adhi-√sthā (estar sobre, presidir)"}, {"iast": "sambhavāmi", "sa": "सम्भवामि", "gram": "1 sg. pres. act.", "es": "me manifiesto, vengo a ser", "analisis": "sam-√bhū (llegar a ser, nacer)"}, {"iast": "ātma-māyayā", "sa": "आत्ममायया", "gram": "instr. sg. f. comp.", "es": "por mi propia māyā", "ref": "maya", "analisis": "ātman (sí mismo, propio) + māyā (poder prodigioso; ilusión)"}], "nota": "<p>El verso responde a la objeción de Arjuna con una paradoja: el que no nace nace; el imperecedero entra en el tiempo; el Señor de los seres se hace uno de ellos. Lo que lo hace posible son dos expresiones discutidas. <em>Prakṛtiṃ svām adhiṣṭhāya</em>, «apoyándome en mi propia naturaleza» o «rigiéndola»: Kṛṣṇa no queda sometido a la naturaleza, como los demás seres (<a class=\"vref\" href=\"capitulo-03.html#v33\" data-v=\"3.33\">3.33</a>), sino que la gobierna. Y <em>ātma-māyayā</em>, «por mi propia <a class=\"t\" href=\"glosario.html#maya\" data-t=\"maya\">māyā</a>»: el poder prodigioso por el que se hace visible. De cómo se entiendan depende que el nacimiento de Kṛṣṇa sea una apariencia o un nacimiento real pero libre (véanse las alternativas de traducción).</p>", "interp": [{"titulo": "Un nacimiento aparente", "html": "<p>Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, el Señor no nace como los demás seres, porque no tiene karma que lo obligue: por su propia māyā, la que está hecha de las tres <a class=\"t\" href=\"glosario.html#guna\" data-t=\"guna\">guṇas</a>, aparece como si tuviera cuerpo y como si naciera, sin que su naturaleza cambie. Desde el punto de vista de la realidad suprema, el nacimiento de Kṛṣṇa es tan aparente como el mundo.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Un nacimiento real y libre", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> defiende que el nacimiento de Kṛṣṇa es real. Lo que lo distingue del de los demás seres es que no está causado por el karma, sino por su libre voluntad, y que en él el Señor conserva su forma divina y todas sus cualidades. Por eso entiende <em>māyā</em> no como ilusión, sino como su propio saber o designio.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "La forma eterna", "html": "<p>La tradición <a class=\"t\" href=\"glosario.html#gaudiya\" data-t=\"gaudiya\">gauḍīya</a> insiste en que el cuerpo con que aparece Kṛṣṇa no es material, sino su forma eterna, que se manifiesta en el mundo por su potencia interna. Bhaktivedanta Swami Prabhupāda lee así <em>ātma-māyayā</em>: no la ilusión que ata a las almas, sino la energía propia del Señor.</p>", "trad": "gaudiya", "tradNombre": "Vaiṣṇavismo gauḍīya"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Aunque soy no nacido y de naturaleza imperecedera, aunque soy el Señor de los seres, rigiendo mi propia <a class=\"t\" href=\"glosario.html#prakrti\" data-t=\"prakrti\">naturaleza</a> aparezco como si naciera, por mi poder de ilusión.", "nota": "<p><em>Māyā</em> es el poder de producir apariencias prodigiosas, y también la ilusión que producen. Si se lee así, Kṛṣṇa no nace de verdad: parece nacer. Es la lectura del <a class=\"t\" href=\"glosario.html#advaita\" data-t=\"advaita\">Advaita</a>: para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, el Señor se muestra «como si tuviera cuerpo, como si naciera», por su propia māyā, y no como nacen los demás seres.</p>"}, {"html": "Aunque soy no nacido y de naturaleza imperecedera, aunque soy el Señor de los seres, permaneciendo en mi propia naturaleza nazco por mi propia voluntad.", "nota": "<p>Otra lectura toma <em>māyā</em> en el sentido védico de «saber, poder, designio»: Kṛṣṇa nace de verdad, pero por libre decisión, no arrastrado por el karma como los demás seres, y sin dejar de ser lo que es. Así lo entiende <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, para quien <em>prakṛtiṃ svām</em> es su propia forma divina, y <em>ātma-māyayā</em>, su propio conocimiento o voluntad.</p>"}], "ens": "descensos-de-krsna"}, {"n": 7, "hablante": "krsna", "sa": ["यदा यदा हि धर्मस्य ग्लानिर्भवति भारत ।", "अभ्युत्थानमधर्मस्य तदात्मानं सृजाम्यहम् ॥७॥"], "iast": ["yadā yadā hi dharmasya glānir bhavati bhārata", "abhyutthānam adharmasya tadātmānaṃ sṛjāmy aham"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Cada vez que decae el <a class=\"t\" href=\"glosario.html#dharma\" data-t=\"dharma\">dharma</a> y se alza el <a class=\"t\" href=\"glosario.html#adharma\" data-t=\"adharma\">adharma</a>, oh <a class=\"t\" href=\"glosario.html#bharata\" data-t=\"bharata\">Bhārata</a>, entonces yo mismo tomo forma.</span>", "palabras": [{"iast": "yadā yadā", "sa": "यदा यदा", "gram": "ind.", "es": "cada vez que"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "en verdad"}, {"iast": "dharmasya", "sa": "धर्मस्य", "gram": "gen. sg. m.", "es": "del dharma", "ref": "dharma"}, {"iast": "glāniḥ", "sa": "ग्लानिः", "gram": "nom. sg. f.", "es": "decaimiento", "analisis": "√glai (agotarse, languidecer)"}, {"iast": "bhavati", "sa": "भवति", "gram": "3 sg. pres. act.", "es": "se produce", "analisis": "√bhū (ser, llegar a ser)"}, {"iast": "bhārata", "sa": "भारत", "gram": "voc. sg. m.", "es": "oh Bhārata", "ref": "bharata"}, {"iast": "abhyutthānam", "sa": "अभ्युत्थानम्", "gram": "nom. sg. n.", "es": "auge, levantamiento", "analisis": "abhi-ut-√sthā (alzarse)"}, {"iast": "adharmasya", "sa": "अधर्मस्य", "gram": "gen. sg. m.", "es": "del adharma", "ref": "adharma"}, {"iast": "tadā", "sa": "तदा", "gram": "ind.", "es": "entonces"}, {"iast": "ātmānam", "sa": "आत्मानम्", "gram": "ac. sg. m.", "es": "a mí mismo"}, {"iast": "sṛjāmi", "sa": "सृजामि", "gram": "1 sg. pres. act.", "es": "doy forma, emito", "analisis": "√sṛj (soltar, emitir, crear)"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}], "nota": "<p><em>Glāni</em> es el agotamiento, el languidecer de algo que pierde fuerza; <em>abhyutthāna</em>, el alzarse de lo contrario. El verbo <em>sṛj</em>, «soltar, emitir, crear», es el mismo con el que se describe la creación del mundo: Kṛṣṇa «se emite a sí mismo», se da forma visible. Con <a class=\"vref\" href=\"capitulo-04.html#v8\" data-v=\"4.8\">4.8</a> forma la formulación más citada de la doctrina del <a class=\"t\" href=\"glosario.html#avatara\" data-t=\"avatara\">avatāra</a>, aunque la palabra <em>avatāra</em> no aparece en la Gītā.</p>", "interp": [{"titulo": "La doctrina del descenso", "html": "<p>La tradición posterior —los Purāṇas, con sus listas de diez o más descensos de <a class=\"t\" href=\"glosario.html#visnu\" data-t=\"visnu\">Viṣṇu</a>— se apoya en estos versos para su doctrina del <a class=\"t\" href=\"glosario.html#avatara\" data-t=\"avatara\">avatāra</a>. En la Gītā la idea es todavía sencilla: no hay lista ni nombres, sino un principio general, «cada vez que». Kṛṣṇa no se presenta como un caso único, sino como una forma de actuar de lo divino que se repite.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "Lo divino que actúa en la historia", "html": "<p>Las lecturas modernas han subrayado el sentido moral e histórico del verso. <a class=\"t\" href=\"glosario.html#gandhi\" data-t=\"gandhi\">Gandhi</a> observa en la introducción a su <em>Anāsaktiyoga</em> que todo ser encarnado es en realidad una encarnación de Dios, aunque no se suele llamar así a cada ser vivo: el hinduismo atribuye ese nombre a quien ha prestado un servicio extraordinario a la humanidad. <a class=\"t\" href=\"glosario.html#aurobindo\" data-t=\"aurobindo\">Śrī Aurobindo</a> dedica varios capítulos de sus <em>Essays on the Gita</em> al «nacimiento divino», que entiende como el modelo de la elevación del ser humano a la naturaleza divina.</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "descensos-de-krsna"}, {"n": 8, "hablante": "krsna", "sa": ["परित्राणाय साधूनां विनाशाय च दुष्कृताम् ।", "धर्मसंस्थापनार्थाय सम्भवामि युगे युगे ॥८॥"], "iast": ["paritrāṇāya sādhūnāṃ vināśāya ca duṣkṛtām", "dharma-saṃsthāpanārthāya sambhavāmi yuge yuge"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Para proteger a los buenos y destruir a los malhechores, para establecer firmemente el <a class=\"t\" href=\"glosario.html#dharma\" data-t=\"dharma\">dharma</a>, me manifiesto en cada <a class=\"t\" href=\"glosario.html#yuga\" data-t=\"yuga\">era</a>.</span>", "palabras": [{"iast": "paritrāṇāya", "sa": "परित्राणाय", "gram": "dat. sg. n.", "es": "para proteger", "analisis": "pari-√trai (proteger por completo)"}, {"iast": "sādhūnām", "sa": "साधूनाम्", "gram": "gen. pl. m.", "es": "a los buenos", "analisis": "sādhu (recto, bueno; el que lleva a término)"}, {"iast": "vināśāya", "sa": "विनाशाय", "gram": "dat. sg. m.", "es": "para destruir", "analisis": "vi-√naś (perecer); vināśa, destrucción"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "duṣkṛtām", "sa": "दुष्कृताम्", "gram": "gen. pl. m.", "es": "a los malhechores", "analisis": "dus (mal) + kṛt (que hace)"}, {"iast": "dharma-saṃsthāpana-arthāya", "sa": "धर्मसंस्थापनार्थाय", "gram": "dat. sg. m. comp.", "es": "para establecer firmemente el dharma", "ref": "dharma", "analisis": "dharma + saṃsthāpana (establecimiento firme; caus. de sam-√sthā) + artha (fin)"}, {"iast": "sambhavāmi", "sa": "सम्भवामि", "gram": "1 sg. pres. act.", "es": "me manifiesto", "analisis": "sam-√bhū (llegar a ser, nacer)"}, {"iast": "yuge yuge", "sa": "युगे युगे", "gram": "loc. sg. n.", "es": "en cada era", "ref": "yuga"}], "nota": "<p>Tres fines para un solo acto: proteger a los buenos (<em>sādhu</em>), destruir a los que obran mal (<em>duṣkṛt</em>) y dar firmeza al <a class=\"t\" href=\"glosario.html#dharma\" data-t=\"dharma\">dharma</a>. <em>Yuge yuge</em>, «en cada era», alude a la doctrina de las cuatro edades del mundo (<a class=\"t\" href=\"glosario.html#yuga\" data-t=\"yuga\">yugas</a>); según la tradición, Kṛṣṇa aparece al final de la tercera, y con su partida comienza la era presente, la de Kali.</p>", "interp": [{"titulo": "Proteger a los que no pueden vivir sin verlo", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> entiende a los «buenos» como los mejores devotos, que no pueden sostener su vida sin ver al Señor; protegerlos es, ante todo, dejarse ver por ellos. La destrucción de los malvados es, en esta lectura, un fin secundario, que el Señor podría lograr con su sola voluntad, sin descender; y el dharma que restablece es su propio culto, que revive cuando él muestra su forma digna de adoración.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "¿Quiénes son los malhechores?", "html": "<p>En el relato, los «malhechores» son Duryodhana y los suyos, y la guerra que va a empezar es la forma de su destrucción. Las lecturas que interiorizan la Gītā, como la de <a class=\"t\" href=\"glosario.html#gandhi\" data-t=\"gandhi\">Gandhi</a>, los leen como las fuerzas del mal en el propio corazón, de modo que el descenso de lo divino ocurre también dentro de cada uno.</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Para salvar a los santos y aniquilar a los malvados, para restablecer el <a class=\"t\" href=\"glosario.html#dharma\" data-t=\"dharma\">dharma</a>, nazco era tras era.", "nota": "<p><em>Saṃsthāpana</em> es «establecer firmemente, consolidar» (el prefijo <em>sam-</em> indica plenitud, no repetición); muchas traducciones dicen «restablecer» porque el verso anterior habla de un dharma que decae. <em>Sādhu</em> es el bueno, el recto, y en la lengua religiosa el santo; <em>sambhavāmi</em>, «vengo a ser», puede traducirse «nazco». Y <em>yuge yuge</em> admite «en cada era» o «era tras era», es decir, una y otra vez.</p>"}], "ens": "descensos-de-krsna"}, {"n": 9, "hablante": "krsna", "sa": ["जन्म कर्म च मे दिव्यमेवं यो वेत्ति तत्त्वतः ।", "त्यक्त्वा देहं पुनर्जन्म नैति मामेति सोऽर्जुन ॥९॥"], "iast": ["janma karma ca me divyam evaṃ yo vetti tattvataḥ", "tyaktvā dehaṃ punar janma naiti mām eti so 'rjuna"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Quien conoce así, en verdad, mi nacimiento y mi <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">obra</a>, que son divinos, al dejar el cuerpo no vuelve a nacer: viene a mí, oh <a class=\"t\" href=\"glosario.html#arjuna\" data-t=\"arjuna\">Arjuna</a>.</span>", "palabras": [{"iast": "janma", "sa": "जन्म", "gram": "ac. sg. n.", "es": "nacimiento"}, {"iast": "karma", "sa": "कर्म", "gram": "ac. sg. n.", "es": "obra, acción", "ref": "karma"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "míos"}, {"iast": "divyam", "sa": "दिव्यम्", "gram": "ac. sg. n. adj.", "es": "divinos", "analisis": "de div (cielo): «celeste, divino»"}, {"iast": "evam", "sa": "एवम्", "gram": "ind.", "es": "así"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. pron.", "es": "quien"}, {"iast": "vetti", "sa": "वेत्ति", "gram": "3 sg. pres. act.", "es": "conoce", "analisis": "√vid (saber)"}, {"iast": "tattvataḥ", "sa": "तत्त्वतः", "gram": "adv.", "es": "en verdad, tal como es", "analisis": "tattva (realidad, lit. «el ser eso») + -tas"}, {"iast": "tyaktvā", "sa": "त्यक्त्वा", "gram": "abs.", "es": "al dejar", "analisis": "√tyaj (abandonar)"}, {"iast": "deham", "sa": "देहम्", "gram": "ac. sg. m.", "es": "el cuerpo"}, {"iast": "punaḥ", "sa": "पुनः", "gram": "ind.", "es": "de nuevo"}, {"iast": "janma", "sa": "जन्म", "gram": "ac. sg. n.", "es": "nacimiento"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "eti", "sa": "एति", "gram": "3 sg. pres. act.", "es": "va (a)", "analisis": "√i (ir)"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "a mí"}, {"iast": "eti", "sa": "एति", "gram": "3 sg. pres. act.", "es": "viene"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "él"}, {"iast": "arjuna", "sa": "अर्जुन", "gram": "voc. sg. m.", "es": "oh Arjuna", "ref": "arjuna"}], "nota": "<p><em>Divya</em>, «divino», califica tanto el nacimiento como la obra de Kṛṣṇa: ni uno ni otra están sometidos al karma. <em>Tattvataḥ</em>, «en verdad, tal como es», distingue este conocimiento de una simple creencia. El juego final es exacto: quien así conoce «no va» (<em>na eti</em>) a un nuevo nacimiento, sino que «va» (<em>eti</em>) a Kṛṣṇa.</p>", "interp": [{"titulo": "Conocer el nacimiento divino", "html": "<p>Para los comentaristas, conocer «en verdad» el nacimiento de Kṛṣṇa es saber que no es como el de los demás seres: no lo produce el karma ni lo limita. Quien comprende esto comprende también la naturaleza de lo divino, y ese conocimiento lo libra de su propio renacimiento.</p>", "trad": "vedanta", "tradNombre": "Vedānta clásico"}, {"titulo": "Ir a Kṛṣṇa", "html": "<p>Las lecturas devocionales subrayan la meta del verso: no un estado impersonal, sino «a mí». Conocer el nacimiento y la obra de Kṛṣṇa —contar y escuchar su historia— es ya un camino de liberación, y de ahí el lugar central que la narración de sus hechos tiene en la devoción posterior.</p>", "trad": "devocional", "tradNombre": "Lecturas devocionales"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "nacimiento-y-obra-divinos"}, {"n": 10, "hablante": "krsna", "sa": ["वीतरागभयक्रोधा मन्मया मामुपाश्रिताः ।", "बहवो ज्ञानतपसा पूता मद्भावमागताः ॥१०॥"], "iast": ["vīta-rāga-bhaya-krodhā man-mayā mām upāśritāḥ", "bahavo jñāna-tapasā pūtā mad-bhāvam āgatāḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Libres de apego, de temor y de <a class=\"t\" href=\"glosario.html#krodha\" data-t=\"krodha\">ira</a>, absortos en mí, refugiados en mí, muchos, purificados por la <a class=\"t\" href=\"glosario.html#tapas\" data-t=\"tapas\">austeridad</a> del <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a>, han llegado a mi modo de ser.</span>", "palabras": [{"iast": "vīta-rāga-bhaya-krodhāḥ", "sa": "वीतरागभयक्रोधाः", "gram": "nom. pl. m. comp.", "es": "libres de apego, temor e ira", "ref": "krodha", "analisis": "vīta (ido, libre de) + rāga (apego) + bhaya (temor) + krodha (ira)"}, {"iast": "man-mayāḥ", "sa": "मन्मयाः", "gram": "nom. pl. m. comp.", "es": "absortos en mí", "analisis": "mad (yo) + -maya (hecho de, lleno de)"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "en mí"}, {"iast": "upāśritāḥ", "sa": "उपाश्रिताः", "gram": "nom. pl. m. ppp", "es": "refugiados", "analisis": "upa-ā-√śri (acogerse a)"}, {"iast": "bahavaḥ", "sa": "बहवः", "gram": "nom. pl. m. adj.", "es": "muchos"}, {"iast": "jñāna-tapasā", "sa": "ज्ञानतपसा", "gram": "instr. sg. n. comp.", "es": "por la austeridad del conocimiento", "ref": "tapas", "analisis": "jñāna (conocimiento) + tapas (ardor, austeridad)"}, {"iast": "pūtāḥ", "sa": "पूताः", "gram": "nom. pl. m. ppp", "es": "purificados", "analisis": "√pū (purificar)"}, {"iast": "mad-bhāvam", "sa": "मद्भावम्", "gram": "ac. sg. m. comp.", "es": "mi modo de ser", "analisis": "mad (yo) + bhāva (estado, naturaleza; afecto)"}, {"iast": "āgatāḥ", "sa": "आगताः", "gram": "nom. pl. m. ppp", "es": "han llegado", "analisis": "ā-√gam (llegar)"}], "nota": "<p>La primera parte repite casi literalmente el retrato del sabio de <a class=\"vref\" href=\"capitulo-02.html#v56\" data-v=\"2.56\">2.56</a>, «libre de apego, de temor y de ira» (<em>vīta-rāga-bhaya-krodhaḥ</em>), y le añade algo nuevo: estar «absortos en mí» y «refugiados en mí». El camino del sabio y el del devoto empiezan a confluir. <em>Jñāna-tapas</em> puede entenderse como «el conocimiento, que es una austeridad» o «la austeridad del conocimiento»: el ardor que purifica no es aquí el del ascetismo corporal, sino el de conocer.</p>", "interp": [{"titulo": "El conocimiento como austeridad", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende <em>jñāna-tapas</em> como el conocimiento que es en sí mismo austeridad, y <em>mad-bhāvam</em> como la condición del Señor, es decir, la liberación. Los «muchos» que la alcanzaron muestran que el camino no es nuevo: es el mismo yoga antiguo de <a class=\"vref\" href=\"capitulo-04.html#v1\" data-v=\"4.1\">4.1</a>.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Libres de apego, de temor y de <a class=\"t\" href=\"glosario.html#krodha\" data-t=\"krodha\">ira</a>, absortos en mí, refugiados en mí, muchos, purificados por la <a class=\"t\" href=\"glosario.html#tapas\" data-t=\"tapas\">austeridad</a> del <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a>, han alcanzado el amor por mí.", "nota": "<p><em>Bhāva</em> es «estado, modo de ser, naturaleza», pero también «sentimiento, afecto». La tradición <a class=\"t\" href=\"glosario.html#gaudiya\" data-t=\"gaudiya\">gauḍīya</a> lo lee en este segundo sentido: Bhaktivedanta Swami Prabhupāda traduce <em>mad-bhāvam</em> como el amor trascendental por Kṛṣṇa. Con «mi modo de ser», el verso habla de una transformación de la naturaleza; con «el amor por mí», de una relación.</p>"}], "ens": "nacimiento-y-obra-divinos"}, {"n": 11, "hablante": "krsna", "sa": ["ये यथा मां प्रपद्यन्ते तांस्तथैव भजाम्यहम् ।", "मम वर्त्मानुवर्तन्ते मनुष्याः पार्थ सर्वशः ॥११॥"], "iast": ["ye yathā māṃ prapadyante tāṃs tathaiva bhajāmy aham", "mama vartmānuvartante manuṣyāḥ pārtha sarvaśaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Como se acercan a mí, así los acojo yo. Los hombres siguen en todo mi camino, oh <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a>.</span>", "palabras": [{"iast": "ye", "sa": "ये", "gram": "nom. pl. m. pron.", "es": "los que, quienes"}, {"iast": "yathā", "sa": "यथा", "gram": "ind.", "es": "como, del modo en que"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "a mí"}, {"iast": "prapadyante", "sa": "प्रपद्यन्ते", "gram": "3 pl. pres. med.", "es": "se acercan, acuden, se refugian", "analisis": "pra-√pad (ir hacia, acudir; refugiarse)"}, {"iast": "tān", "sa": "तान्", "gram": "ac. pl. m. pron.", "es": "a ellos"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "así"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "precisamente, del mismo modo"}, {"iast": "bhajāmi", "sa": "भजामि", "gram": "1 sg. pres. act.", "es": "acojo, correspondo", "analisis": "√bhaj (dar a cada uno su parte; honrar, amar); la misma raíz que bhakti"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "mama", "sa": "मम", "gram": "gen. sg. pron.", "es": "mi, de mí"}, {"iast": "vartma", "sa": "वर्त्म", "gram": "ac. sg. n.", "es": "camino, senda", "analisis": "vartman, de √vṛt (girar, moverse)"}, {"iast": "anuvartante", "sa": "अनुवर्तन्ते", "gram": "3 pl. pres. med.", "es": "siguen", "analisis": "anu-√vṛt (moverse detrás de, seguir)"}, {"iast": "manuṣyāḥ", "sa": "मनुष्याः", "gram": "nom. pl. m.", "es": "los hombres, los seres humanos"}, {"iast": "pārtha", "sa": "पार्थ", "gram": "voc. sg. m.", "es": "oh Pārtha", "ref": "partha"}, {"iast": "sarvaśaḥ", "sa": "सर्वशः", "gram": "ind.", "es": "en todo, de todos modos, en todas partes", "analisis": "sarva (todo) + -śaḥ (sufijo distributivo)"}], "nota": "<p>Después de anunciar sus descensos para proteger a los buenos y destruir a los malvados (<a class=\"vref\" href=\"capitulo-04.html#v7\" data-v=\"4.7\">4.7</a>–<a class=\"vref\" href=\"capitulo-04.html#v8\" data-v=\"4.8\">4.8</a>), Kṛṣṇa sale al paso de una objeción implícita: ¿no es Dios parcial, si favorece a unos y castiga a otros? No: acoge a cada uno según el modo en que se acerca a él. <em>Bhajāmi</em>, «acojo, correspondo», es de la raíz √bhaj, la misma de <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">bhakti</a>: dar a cada uno su parte, y también honrar y amar.</p><p>La segunda mitad repite palabra por palabra la de <a class=\"vref\" href=\"capitulo-03.html#v23\" data-v=\"3.23\">3.23</a>. Allí «mi camino» era el ejemplo de conducta de Kṛṣṇa; aquí, tras hablar de cómo se acercan a él los hombres, admite también otro sentido (véanse las alternativas).</p>", "interp": [{"titulo": "Cada cual recibe lo que busca", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lee el verso como respuesta a la objeción de parcialidad: el Señor corresponde a cada uno según lo que busca, y da el fruto a quien desea frutos, el conocimiento a quien busca la liberación sin desear frutos, la liberación a los sabios renunciantes y el alivio a los afligidos; no actúa por apego, por aversión ni por ofuscación. La segunda mitad la entiende en el mismo sentido: sean cuales sean las obras a que se dedican según el fruto que buscan, los hombres siguen de todos modos el camino del Señor, que está presente en todo.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Todos los caminos", "html": "<p>Swami Vivekananda citó este verso en su primer discurso ante el Parlamento de las Religiones de Chicago, el 11 de septiembre de 1893, como expresión de la tolerancia que, a su juicio, enseña el hinduismo: sea cual sea la forma en que alguien se acerca a Dios, Dios lo acoge, y todos los caminos conducen a él. Esa lectura pluralista se volvió una de las más influyentes del hinduismo moderno.</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}, {"titulo": "Dos veces la misma media estrofa", "html": "<p>La segunda mitad del verso es idéntica a la de <a class=\"vref\" href=\"capitulo-03.html#v23\" data-v=\"3.23\">3.23</a>. Allí, en un contexto de ejemplo y de imitación, «mi camino» es la conducta de Kṛṣṇa; aquí, tras hablar de cómo se acercan a él los hombres, el mismo «mi camino» puede entenderse como la meta común de todas las vías. La repetición sugiere que la frase era una fórmula, y el doble contexto explica que se haya leído de dos maneras.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Como se acercan a mí, así los acojo yo; por cualquier camino que vayan, oh <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a>, los hombres siguen el mío.", "nota": "<p><em>Sarvaśaḥ</em>, «en todo, de todos modos, por todas partes», y <em>mama vartma</em>, «mi camino», admiten esta lectura: sea cual sea la vía que alguien siga, es la de Kṛṣṇa. Es la que popularizó Vivekananda en el Parlamento de las Religiones de Chicago (1893). La traducción principal es más literal y conserva el paralelo exacto con <a class=\"vref\" href=\"capitulo-03.html#v23\" data-v=\"3.23\">3.23</a>, donde la misma media estrofa significa que los hombres siguen el ejemplo de Kṛṣṇa.</p>"}], "ens": "como-se-acercan"}, {"n": 12, "hablante": "krsna", "sa": ["काङ्क्षन्तः कर्मणां सिद्धिं यजन्त इह देवताः ।", "क्षिप्रं हि मानुषे लोके सिद्धिर्भवति कर्मजा ॥१२॥"], "iast": ["kāṅkṣantaḥ karmaṇāṃ siddhiṃ yajanta iha devatāḥ", "kṣipraṃ hi mānuṣe loke siddhir bhavati karma-jā"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Los que desean el éxito de sus obras ofrecen aquí sacrificios a las divinidades: pues en el mundo de los hombres el éxito nacido de la acción llega pronto.</span>", "palabras": [{"iast": "kāṅkṣantaḥ", "sa": "काङ्क्षन्तः", "gram": "nom. pl. m. part. pres. act.", "es": "deseando", "analisis": "√kāṅkṣ (desear, anhelar)"}, {"iast": "karmaṇām", "sa": "कर्मणाम्", "gram": "gen. pl. n.", "es": "de las acciones, de las obras", "ref": "karma"}, {"iast": "siddhim", "sa": "सिद्धिम्", "gram": "ac. sg. f.", "es": "el éxito, el logro", "analisis": "√sidh (lograr, cumplirse)"}, {"iast": "yajante", "sa": "यजन्ते", "gram": "3 pl. pres. med.", "es": "ofrecen sacrificio, rinden culto", "ref": "yajna", "analisis": "√yaj (sacrificar, honrar con ofrendas)"}, {"iast": "iha", "sa": "इह", "gram": "ind.", "es": "aquí, en este mundo"}, {"iast": "devatāḥ", "sa": "देवताः", "gram": "ac. pl. f.", "es": "a las divinidades", "ref": "deva", "analisis": "devatā, abstracto de deva: «divinidad»"}, {"iast": "kṣipram", "sa": "क्षिप्रम्", "gram": "ind.", "es": "pronto, rápidamente"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues"}, {"iast": "mānuṣe", "sa": "मानुषे", "gram": "loc. sg. m. adj.", "es": "humano, de los hombres"}, {"iast": "loke", "sa": "लोके", "gram": "loc. sg. m.", "es": "en el mundo"}, {"iast": "siddhiḥ", "sa": "सिद्धिः", "gram": "nom. sg. f.", "es": "el éxito"}, {"iast": "bhavati", "sa": "भवति", "gram": "3 sg. pres. act.", "es": "llega, se produce", "analisis": "√bhū (ser, llegar a ser)"}, {"iast": "karma-jā", "sa": "कर्मजा", "gram": "nom. sg. f. adj. comp.", "es": "nacido de la acción", "analisis": "karman (acción) + ja (nacido de)"}], "nota": "<p><em>Devatā</em> son las divinidades a las que se dirige el rito védico (<a class=\"vref\" href=\"capitulo-03.html#v11\" data-v=\"3.11\">3.11</a>). Kṛṣṇa constata un hecho: el rito interesado funciona, y su fruto llega pronto en el mundo de los hombres. No lo condena aquí, pero lo sitúa por debajo de lo que acaba de decir: quien lo busca a él no busca el éxito de las obras, sino algo distinto (<a class=\"vref\" href=\"capitulo-04.html#v9\" data-v=\"4.9\">4.9</a>–<a class=\"vref\" href=\"capitulo-04.html#v10\" data-v=\"4.10\">4.10</a>). Volverá sobre quienes adoran a otras divinidades en <a class=\"vref\" href=\"capitulo-07.html#v20\" data-v=\"7.20\">7.20</a>–<a class=\"vref\" href=\"capitulo-07.html#v23\" data-v=\"7.23\">7.23</a> y <a class=\"vref\" href=\"capitulo-09.html#v23\" data-v=\"9.23\">9.23</a>.</p>", "interp": [{"titulo": "El fruto rápido y el fruto lento", "html": "<p>Los comentaristas leen el verso como explicación de por qué no todos buscan la liberación: quienes desean el fruto de sus obras adoran a otras divinidades, y ese fruto llega pronto. <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> ve en ello la ignorancia de quien adora a una divinidad como distinta de sí mismo; <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> añade que el fruto del conocimiento, la liberación, es difícil de alcanzar, y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, que tarda porque exige antes purificar la mente. La Gītā no desprecia el culto a las divinidades, pero lo pone en su lugar: da lo que promete, que no es lo más alto.</p>", "trad": "vedanta", "tradNombre": "Vedānta clásico"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 13, "hablante": "krsna", "sa": ["चातुर्वर्ण्यं मया सृष्टं गुणकर्मविभागशः ।", "तस्य कर्तारमपि मां विद्ध्यकर्तारमव्ययम् ॥१३॥"], "iast": ["cātur-varṇyaṃ mayā sṛṣṭaṃ guṇa-karma-vibhāgaśaḥ", "tasya kartāram api māṃ viddhy akartāram avyayam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">El orden de las cuatro <a class=\"t\" href=\"glosario.html#varna\" data-t=\"varna\">clases</a> lo creé yo, según la distribución de las <a class=\"t\" href=\"glosario.html#guna\" data-t=\"guna\">guṇas</a> y de las <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acciones</a>. Sabe que, aun siendo su autor, no soy agente y permanezco inmutable.</span>", "palabras": [{"iast": "cātur-varṇyam", "sa": "चातुर्वर्ण्यम्", "gram": "nom. sg. n. comp.", "es": "el orden de las cuatro clases", "ref": "varna", "analisis": "catur (cuatro) + varṇa (clase), con alargamiento de la primera vocal: abstracto, «el conjunto de las cuatro clases»"}, {"iast": "mayā", "sa": "मया", "gram": "instr. sg. pron.", "es": "por mí"}, {"iast": "sṛṣṭam", "sa": "सृष्टम्", "gram": "nom. sg. n. ppp", "es": "creado", "analisis": "√sṛj (emitir, crear)"}, {"iast": "guṇa-karma-vibhāgaśaḥ", "sa": "गुणकर्मविभागशः", "gram": "ind. comp.", "es": "según la distribución de las guṇas y de las acciones", "ref": "guna", "analisis": "guṇa (cualidad) + karman (acción) + vibhāga (división, reparto) + -śaḥ (según)"}, {"iast": "tasya", "sa": "तस्य", "gram": "gen. sg. n. pron.", "es": "de él (de ese orden)"}, {"iast": "kartāram", "sa": "कर्तारम्", "gram": "ac. sg. m.", "es": "autor, agente", "analisis": "kartṛ, de √kṛ (hacer)"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "aun, aunque"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "a mí"}, {"iast": "viddhi", "sa": "विद्धि", "gram": "2 sg. impv. act.", "es": "sabe", "analisis": "√vid (saber)"}, {"iast": "akartāram", "sa": "अकर्तारम्", "gram": "ac. sg. m.", "es": "no agente", "analisis": "a (no) + kartṛ (agente)"}, {"iast": "avyayam", "sa": "अव्ययम्", "gram": "ac. sg. m. adj.", "es": "inmutable, imperecedero", "analisis": "a (no) + vyaya (merma, pérdida)"}], "nota": "<p><em>Cātur-varṇyam</em> es un abstracto: «el conjunto de las cuatro clases», el orden de los <a class=\"t\" href=\"glosario.html#varna\" data-t=\"varna\">varṇas</a>. <em>Guṇa-karma-vibhāgaśaḥ</em>, «según la distribución de guṇas y acciones», es la clave del verso y de su larga discusión. La teoría de las <a class=\"t\" href=\"glosario.html#guna\" data-t=\"guna\">guṇas</a> (<a class=\"vref\" href=\"capitulo-03.html#v27\" data-v=\"3.27\">3.27</a>–<a class=\"vref\" href=\"capitulo-03.html#v29\" data-v=\"3.29\">3.29</a>) ofrece el criterio: cada clase correspondería a una proporción distinta de <a class=\"t\" href=\"glosario.html#sattva\" data-t=\"sattva\">sattva</a>, <a class=\"t\" href=\"glosario.html#rajas\" data-t=\"rajas\">rajas</a> y <a class=\"t\" href=\"glosario.html#tamas\" data-t=\"tamas\">tamas</a>. Los deberes de cada clase «nacidos de su propia naturaleza» se detallan en <a class=\"vref\" href=\"capitulo-18.html#v41\" data-v=\"18.41\">18.41</a>–<a class=\"vref\" href=\"capitulo-18.html#v44\" data-v=\"18.44\">18.44</a>.</p><p>La segunda mitad formula una paradoja que el verso siguiente explica: Kṛṣṇa es autor de ese orden, pero no agente, porque no actúa movido por el deseo ni queda atado por lo que hace.</p>", "interp": [{"titulo": "Las guṇas de cada clase", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> explica la «distribución de guṇas» con una correspondencia que se hizo clásica: en el brāhmaṇa predomina sattva; en el kṣatriya, rajas, subordinado a él sattva; en el vaiśya, rajas, subordinado a él tamas; en el śūdra, tamas, subordinado a él rajas. Y resuelve la paradoja final distinguiendo planos: el Señor es autor de ese orden en el plano de la experiencia ordinaria, regida por la <em>māyā</em>, pero en realidad no actúa.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Por cualidades, no por nacimiento", "html": "<p>Los reformistas de los siglos XIX y XX hicieron de este verso su texto clave. Subrayando que habla de «guṇas y acciones» y no de nacimiento, lo leyeron como una clasificación por temperamento y vocación: así <a class=\"t\" href=\"glosario.html#aurobindo\" data-t=\"aurobindo\">Aurobindo</a>, que entiende el varṇa como expresión de la naturaleza interior de cada uno (<em>svabhāva</em>). <a class=\"t\" href=\"glosario.html#gandhi\" data-t=\"gandhi\">Gandhi</a> defendió durante años un varṇa hereditario, entendido como reparto de oficios sin jerarquía de dignidad, a la vez que combatía la intocabilidad.</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}, {"titulo": "Una teología del orden social", "html": "<p>Para la crítica histórica, el verso da un fundamento divino al orden de las cuatro clases de los tratados de derecho brahmánico: si el propio Dios lo creó, forma parte del orden del mundo. La teoría de las guṇas lo naturaliza, y la mención de la «acción» lo une a la ética del deber propio (<a class=\"vref\" href=\"capitulo-03.html#v35\" data-v=\"3.35\">3.35</a>). Pero, precisamente porque no habla de nacimiento, el verso quedó abierto a la reinterpretación moderna.</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Las cuatro <a class=\"t\" href=\"glosario.html#varna\" data-t=\"varna\">clases</a> las creé yo según las cualidades y las tareas de cada cual. Sabe que, aun siendo su autor, no soy agente y permanezco inmutable.", "nota": "<p><em>Guṇa</em> puede entenderse como las cualidades de cada persona, y <em>karman</em> como su tarea o función, no como la acción en general. Así leído, el verso describe una clasificación según el temperamento y el oficio de cada uno: es la lectura de los reformistas modernos. La traducción principal deja «guṇas y acciones» sin decidir si el reparto se hace persona por persona o, como entendía la tradición, por nacimiento: el sánscrito no menciona el nacimiento, ni para afirmarlo ni para negarlo.</p>"}], "ens": "autor-sin-ser-agente"}, {"n": 14, "hablante": "krsna", "sa": ["न मां कर्माणि लिम्पन्ति न मे कर्मफले स्पृहा ।", "इति मां योऽभिजानाति कर्मभिर्न स बध्यते ॥१४॥"], "iast": ["na māṃ karmāṇi limpanti na me karma-phale spṛhā", "iti māṃ yo 'bhijānāti karmabhir na sa badhyate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Las acciones no me manchan, ni deseo yo el fruto de la acción. Quien me conoce así no queda atado por las acciones.</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "a mí"}, {"iast": "karmāṇi", "sa": "कर्माणि", "gram": "nom. pl. n.", "es": "las acciones", "ref": "karma"}, {"iast": "limpanti", "sa": "लिम्पन्ति", "gram": "3 pl. pres. act.", "es": "manchan", "analisis": "√lip (untar, manchar)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "en mí, para mí"}, {"iast": "karma-phale", "sa": "कर्मफले", "gram": "loc. sg. n. comp.", "es": "en el fruto de la acción", "ref": "phala", "analisis": "karman (acción) + phala (fruto)"}, {"iast": "spṛhā", "sa": "स्पृहा", "gram": "nom. sg. f.", "es": "deseo, anhelo", "analisis": "√spṛh (anhelar)"}, {"iast": "iti", "sa": "इति", "gram": "ind.", "es": "así"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "a mí"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. pron.", "es": "quien"}, {"iast": "abhijānāti", "sa": "अभिजानाति", "gram": "3 sg. pres. act.", "es": "conoce (a fondo)", "analisis": "abhi-√jñā (conocer, reconocer)"}, {"iast": "karmabhiḥ", "sa": "कर्मभिः", "gram": "instr. pl. n.", "es": "por las acciones"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "él"}, {"iast": "badhyate", "sa": "बध्यते", "gram": "3 sg. pres. pas.", "es": "queda atado", "analisis": "√bandh (atar)"}], "nota": "<p>Explica la paradoja de <a class=\"vref\" href=\"capitulo-04.html#v13\" data-v=\"4.13\">4.13</a>: lo que mancha no es la acción, sino el deseo de su <a class=\"t\" href=\"glosario.html#phala\" data-t=\"phala\">fruto</a>, y en Kṛṣṇa no lo hay; nada le falta, y aun así actúa (<a class=\"vref\" href=\"capitulo-03.html#v22\" data-v=\"3.22\">3.22</a>). Quien comprende esto —que el obrar sin deseo no ata— queda libre a su vez. Es el principio que <a class=\"vref\" href=\"capitulo-02.html#v47\" data-v=\"2.47\">2.47</a> enseñó como técnica, ahora mostrado en el propio Dios.</p>", "interp": [{"titulo": "Conocerlo como el propio sí-mismo", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> explica que las acciones no manchan al Señor porque no tiene <a class=\"t\" href=\"glosario.html#ahankara\" data-t=\"ahankara\">sentido del yo</a> que se las atribuya ni deseo de su fruto. Y entiende el «quien me conoce así» como quien conoce así al Señor como su propio sí-mismo: tampoco a él lo atan las acciones.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Dios como modelo", "html": "<p>El verso aplica a Dios lo que <a class=\"vref\" href=\"capitulo-02.html#v47\" data-v=\"2.47\">2.47</a>–<a class=\"vref\" href=\"capitulo-02.html#v48\" data-v=\"2.48\">2.48</a> enseñaban al hombre: obrar sin deseo del fruto no ata. Conocer así a Kṛṣṇa no es sólo saber algo de él; es aprender de él la manera de actuar, y por eso el verso siguiente pasa directamente a la exhortación.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "autor-sin-ser-agente"}, {"n": 15, "hablante": "krsna", "sa": ["एवं ज्ञात्वा कृतं कर्म पूर्वैरपि मुमुक्षुभिः ।", "कुरु कर्मैव तस्मात्त्वं पूर्वैः पूर्वतरं कृतम् ॥१५॥"], "iast": ["evaṃ jñātvā kṛtaṃ karma pūrvair api mumukṣubhiḥ", "kuru karmaiva tasmāt tvaṃ pūrvaiḥ pūrvataraṃ kṛtam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Sabiéndolo así actuaron también los antiguos que buscaban la <a class=\"t\" href=\"glosario.html#moksa\" data-t=\"moksa\">liberación</a>. Realiza, pues, tú también la <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a>, como la realizaron los antiguos desde los tiempos más remotos.</span>", "palabras": [{"iast": "evam", "sa": "एवम्", "gram": "ind.", "es": "así"}, {"iast": "jñātvā", "sa": "ज्ञात्वा", "gram": "abs.", "es": "sabiendo", "analisis": "√jñā (conocer)"}, {"iast": "kṛtam", "sa": "कृतम्", "gram": "nom. sg. n. ppp", "es": "fue realizada", "analisis": "√kṛ (hacer)"}, {"iast": "karma", "sa": "कर्म", "gram": "nom. sg. n.", "es": "la acción", "ref": "karma"}, {"iast": "pūrvaiḥ", "sa": "पूर्वैः", "gram": "instr. pl. m.", "es": "por los antiguos"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "también"}, {"iast": "mumukṣubhiḥ", "sa": "मुमुक्षुभिः", "gram": "instr. pl. m. adj. desid.", "es": "que deseaban la liberación", "ref": "moksa", "analisis": "desiderativo de √muc (soltar, liberar)"}, {"iast": "kuru", "sa": "कुरु", "gram": "2 sg. impv. act.", "es": "haz, realiza", "analisis": "√kṛ (hacer)"}, {"iast": "karma", "sa": "कर्म", "gram": "ac. sg. n.", "es": "la acción"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "precisamente"}, {"iast": "tasmāt", "sa": "तस्मात्", "gram": "abl. sg. pron.", "es": "por eso"}, {"iast": "tvam", "sa": "त्वम्", "gram": "nom. sg. pron.", "es": "tú"}, {"iast": "pūrvaiḥ", "sa": "पूर्वैः", "gram": "instr. pl. m.", "es": "por los antiguos"}, {"iast": "pūrvataram", "sa": "पूर्वतरम्", "gram": "ind.", "es": "más antiguamente, desde tiempos aún más remotos", "analisis": "pūrva (anterior) + -tara (comparativo)"}, {"iast": "kṛtam", "sa": "कृतम्", "gram": "ac. sg. n. ppp", "es": "realizada"}], "nota": "<p><em>Mumukṣu</em>, «el que desea la liberación», es desiderativo de √muc, «soltar». <em>Pūrvaiḥ pūrvataraṃ kṛtam</em>, literalmente «hecha por los antiguos, más antiguamente», insiste en la antigüedad de esta práctica y enlaza con la tradición de reyes sabios del comienzo del capítulo (<a class=\"vref\" href=\"capitulo-04.html#v1\" data-v=\"4.1\">4.1</a>–<a class=\"vref\" href=\"capitulo-04.html#v3\" data-v=\"4.3\">4.3</a>) y con <a class=\"t\" href=\"glosario.html#janaka\" data-t=\"janaka\">Janaka</a> y los demás de <a class=\"vref\" href=\"capitulo-03.html#v20\" data-v=\"3.20\">3.20</a>. Con este verso se cierra el argumento: si Dios actúa sin quedar atado, y los antiguos actuaron así, también Arjuna puede y debe hacerlo.</p>", "interp": [{"titulo": "Para purificarse o por el mundo", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> distingue dos casos: si Arjuna todavía no conoce el sí-mismo, debe actuar para purificarse; si ya lo conoce, debe actuar por el bien del mundo (<a class=\"t\" href=\"glosario.html#lokasangraha\" data-t=\"lokasangraha\">loka-saṃgraha</a>, <a class=\"vref\" href=\"capitulo-03.html#v20\" data-v=\"3.20\">3.20</a>). En ninguno de los dos le conviene abandonar la acción.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 16, "hablante": "krsna", "sa": ["किं कर्म किमकर्मेति कवयोऽप्यत्र मोहिताः ।", "तत्ते कर्म प्रवक्ष्यामि यज्ज्ञात्वा मोक्ष्यसेऽशुभात् ॥१६॥"], "iast": ["kiṃ karma kim akarmeti kavayo 'py atra mohitāḥ", "tat te karma pravakṣyāmi yaj jñātvā mokṣyase 'śubhāt"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">¿Qué es la <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a>? ¿Qué es la <a class=\"t\" href=\"glosario.html#akarma\" data-t=\"akarma\">inacción</a>? En esto se extravían aun los sabios. Por eso te explicaré qué es la acción; sabiéndolo, quedarás libre del mal.</span>", "palabras": [{"iast": "kim", "sa": "किम्", "gram": "nom. sg. n. pron.", "es": "¿qué?"}, {"iast": "karma", "sa": "कर्म", "gram": "nom. sg. n.", "es": "la acción", "ref": "karma"}, {"iast": "kim", "sa": "किम्", "gram": "nom. sg. n. pron.", "es": "¿qué?"}, {"iast": "akarma", "sa": "अकर्म", "gram": "nom. sg. n.", "es": "la inacción", "ref": "akarma", "analisis": "a- (no) + karman (acción)"}, {"iast": "iti", "sa": "इति", "gram": "ind.", "es": "así (cierra la pregunta)"}, {"iast": "kavayaḥ", "sa": "कवयः", "gram": "nom. pl. m.", "es": "los sabios, los videntes", "analisis": "kavi: poeta, vidente, sabio inspirado"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "aun, incluso"}, {"iast": "atra", "sa": "अत्र", "gram": "ind.", "es": "en esto"}, {"iast": "mohitāḥ", "sa": "मोहिताः", "gram": "nom. pl. m. ppp caus.", "es": "se extravían, están confundidos", "ref": "moha", "analisis": "causativo de √muh (extraviarse, ofuscarse)"}, {"iast": "tat", "sa": "तत्", "gram": "ac. sg. n. pron.", "es": "eso, esa"}, {"iast": "te", "sa": "ते", "gram": "dat. sg. pron.", "es": "a ti"}, {"iast": "karma", "sa": "कर्म", "gram": "ac. sg. n.", "es": "la acción", "ref": "karma"}, {"iast": "pravakṣyāmi", "sa": "प्रवक्ष्यामि", "gram": "1 sg. fut. act.", "es": "explicaré", "analisis": "pra-√vac (declarar, exponer)"}, {"iast": "yat", "sa": "यत्", "gram": "ac. sg. n. pron.", "es": "lo cual"}, {"iast": "jñātvā", "sa": "ज्ञात्वा", "gram": "abs.", "es": "sabiendo, una vez conocido", "analisis": "√jñā (conocer)"}, {"iast": "mokṣyase", "sa": "मोक्ष्यसे", "gram": "2 sg. fut. med.", "es": "quedarás libre", "ref": "moksa", "analisis": "√muc (soltar, liberar)"}, {"iast": "aśubhāt", "sa": "अशुभात्", "gram": "abl. sg. n.", "es": "del mal", "analisis": "a- (no) + śubha (propicio, bueno)"}], "nota": "<p>Kṛṣṇa anuncia una explicación de la acción y empieza por reconocer que la pregunta es difícil: aun los <em>kavi</em>, «los videntes, los sabios inspirados», se extravían en ella. La pregunta recoge, en términos generales, la perplejidad de Arjuna en <a class=\"vref\" href=\"capitulo-03.html#v1\" data-v=\"3.1\">3.1</a>–<a class=\"vref\" href=\"capitulo-03.html#v2\" data-v=\"3.2\">3.2</a>.</p><p><em>Aśubha</em>, «lo no propicio», es el mal en sentido amplio: la falta moral y, para los comentaristas vedánticos, el ciclo de renacimientos (<a class=\"t\" href=\"glosario.html#samsara\" data-t=\"samsara\">saṃsāra</a>) del que libra el conocimiento.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 17, "hablante": "krsna", "sa": ["कर्मणो ह्यपि बोद्धव्यं बोद्धव्यं च विकर्मणः ।", "अकर्मणश्च बोद्धव्यं गहना कर्मणो गतिः ॥१७॥"], "iast": ["karmaṇo hy api boddhavyaṃ boddhavyaṃ ca vikarmaṇaḥ", "akarmaṇaś ca boddhavyaṃ gahanā karmaṇo gatiḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Pues hay que entender qué es la <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a>, hay que entender qué es la <a class=\"t\" href=\"glosario.html#vikarma\" data-t=\"vikarma\">acción indebida</a> y hay que entender qué es la <a class=\"t\" href=\"glosario.html#akarma\" data-t=\"akarma\">inacción</a>: profundo es el camino de la acción.</span>", "palabras": [{"iast": "karmaṇaḥ", "sa": "कर्मणः", "gram": "gen. sg. n.", "es": "de la acción", "ref": "karma"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "también"}, {"iast": "boddhavyam", "sa": "बोद्धव्यम्", "gram": "nom. sg. n. gerundivo", "es": "ha de entenderse", "analisis": "√budh (comprender, darse cuenta)"}, {"iast": "boddhavyam", "sa": "बोद्धव्यम्", "gram": "nom. sg. n. gerundivo", "es": "ha de entenderse", "analisis": "√budh"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "vikarmaṇaḥ", "sa": "विकर्मणः", "gram": "gen. sg. n.", "es": "de la acción indebida", "ref": "vikarma", "analisis": "vi- (desvío, separación; también diversidad) + karman (acción)"}, {"iast": "akarmaṇaḥ", "sa": "अकर्मणः", "gram": "gen. sg. n.", "es": "de la inacción", "ref": "akarma", "analisis": "a- (no) + karman"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "boddhavyam", "sa": "बोद्धव्यम्", "gram": "nom. sg. n. gerundivo", "es": "ha de entenderse", "analisis": "√budh"}, {"iast": "gahanā", "sa": "गहना", "gram": "nom. sg. f. adj.", "es": "profunda, difícil de penetrar", "analisis": "gahana: espeso, impenetrable, como un bosque"}, {"iast": "karmaṇaḥ", "sa": "कर्मणः", "gram": "gen. sg. n.", "es": "de la acción", "ref": "karma"}, {"iast": "gatiḥ", "sa": "गतिः", "gram": "nom. sg. f.", "es": "el camino, el curso", "analisis": "√gam (ir)"}], "nota": "<p>Tres términos: la acción (<em>karman</em>), la acción indebida (<a class=\"t\" href=\"glosario.html#vikarma\" data-t=\"vikarma\"><em>vikarman</em></a>) y la inacción (<a class=\"t\" href=\"glosario.html#akarma\" data-t=\"akarma\"><em>akarman</em></a>). Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, <em>karman</em> es aquí la acción prescrita por las escrituras, <em>vikarman</em> la prohibida, y <em>akarman</em> la abstención de obrar; también <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a> entienden <em>vikarman</em> como la acción prohibida. <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, en cambio, entiende <em>vikarman</em> como la acción en sus diversas formas (ritos obligatorios, ocasionales y opcionales, y lo necesario para realizarlos), y <em>akarman</em> como el conocimiento del sí-mismo.</p><p><em>Gahana</em> se dice de un bosque espeso, en el que es fácil perderse: el «camino» o «curso» de la acción (<em>gati</em>) es difícil de seguir hasta el fondo. La frase recuerda que la cuestión no se resuelve con una regla, sino con una manera de ver, la que formula el verso siguiente.</p>", "interp": [{"titulo": "Tres maneras de obrar", "html": "<p>El verso no define los tres términos; sólo pide entenderlos. Con <em>vikarman</em>, que sólo aparece aquí, la lectura más extendida entre los comentaristas completa el cuadro del derecho brahmánico: hay acciones prescritas, acciones prohibidas y la posibilidad de abstenerse. Pero el verso siguiente desplaza la cuestión: lo decisivo no es qué se hace, sino cómo se ve el hacer, y por eso la distinción entre acción e inacción deja de coincidir con la de moverse o quedarse quieto.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Pues hay que entender qué es la <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a>, hay que entender la acción en sus diversas formas y hay que entender qué es la <a class=\"t\" href=\"glosario.html#akarma\" data-t=\"akarma\">inacción</a>: profundo es el camino de la acción.", "nota": "<p>El prefijo <em>vi-</em> puede indicar desvío («acción desviada, contraria a lo debido») o diversidad y distinción («acción diversa, especial»). La lectura clásica, que sigue la traducción principal, entiende <em>vikarman</em> como la acción prohibida; otras, como la de <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, que Vedānta Deśika defiende expresamente frente a la glosa «prohibida», toman el término en el segundo sentido, como las múltiples formas que puede adoptar el obrar. <em>Vikarman</em> sólo aparece aquí en la Gītā, y el texto no lo define.</p>"}], "ens": "inaccion-en-la-accion"}, {"n": 18, "hablante": "krsna", "sa": ["कर्मण्यकर्म यः पश्येदकर्मणि च कर्म यः ।", "स बुद्धिमान्मनुष्येषु स युक्तः कृत्स्नकर्मकृत् ॥१८॥"], "iast": ["karmaṇy akarma yaḥ paśyed akarmaṇi ca karma yaḥ", "sa buddhimān manuṣyeṣu sa yuktaḥ kṛtsna-karma-kṛt"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Quien ve la <a class=\"t\" href=\"glosario.html#akarma\" data-t=\"akarma\">inacción</a> en la <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a> y la acción en la inacción, ése es, entre los hombres, el que tiene <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a>; ése está unido en <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a> y lleva a cabo toda acción.</span>", "palabras": [{"iast": "karmaṇi", "sa": "कर्मणि", "gram": "loc. sg. n.", "es": "en la acción", "ref": "karma"}, {"iast": "akarma", "sa": "अकर्म", "gram": "ac. sg. n.", "es": "la inacción", "ref": "akarma"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. pron.", "es": "quien"}, {"iast": "paśyet", "sa": "पश्येत्", "gram": "3 sg. opt. act.", "es": "vea", "analisis": "√paś / √dṛś (ver)"}, {"iast": "akarmaṇi", "sa": "अकर्मणि", "gram": "loc. sg. n.", "es": "en la inacción", "ref": "akarma"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "karma", "sa": "कर्म", "gram": "ac. sg. n.", "es": "la acción", "ref": "karma"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. pron.", "es": "quien"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "ése"}, {"iast": "buddhimān", "sa": "बुद्धिमान्", "gram": "nom. sg. m. adj.", "es": "el que tiene entendimiento", "ref": "buddhi", "analisis": "buddhi (entendimiento) + -mat (que posee)"}, {"iast": "manuṣyeṣu", "sa": "मनुष्येषु", "gram": "loc. pl. m.", "es": "entre los hombres"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "ése"}, {"iast": "yuktaḥ", "sa": "युक्तः", "gram": "nom. sg. m. ppp", "es": "unido en yoga, disciplinado", "ref": "yoga", "analisis": "√yuj (uncir, unir)"}, {"iast": "kṛtsna-karma-kṛt", "sa": "कृत्स्नकर्मकृत्", "gram": "nom. sg. m. comp.", "es": "el que realiza toda acción", "analisis": "kṛtsna (entero, todo) + karman (acción) + kṛt (que hace, de √kṛ)"}], "nota": "<p>El verso más paradójico del capítulo, construido como un quiasmo: inacción en la acción, acción en la inacción. No prescribe qué hacer, sino cómo ver, y por eso llama a quien así ve <em>buddhimān</em>, «el que tiene entendimiento».</p><p><em>Kṛtsna-karma-kṛt</em>, «el que realiza toda acción», puede leerse como elogio (ha cumplido cuanto había que cumplir) o como paradoja (aun realizando toda clase de acciones, no queda atado). Los versos siguientes (<a class=\"vref\" href=\"capitulo-04.html#v19\" data-v=\"4.19\">4.19</a>–<a class=\"vref\" href=\"capitulo-04.html#v23\" data-v=\"4.23\">4.23</a>) describen a ese hombre.</p>", "interp": [{"titulo": "El sí-mismo que no actúa", "html": "<p>Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, la clave es que el <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">sí-mismo</a> nunca actúa: la acción pertenece al cuerpo, los sentidos y la mente, y el ignorante se la atribuye a sí mismo. Ver la inacción en la acción es reconocer, mientras el cuerpo obra, que uno no es su agente. Ver la acción en la inacción es comprender que también la quietud de quien se abstiene, si se la atribuye a sí mismo («estoy sentado sin hacer nada»), es una acción nacida de la misma identificación con el cuerpo.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "La acción que contiene el conocimiento", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> entiende aquí <em>akarman</em> como el conocimiento del sí-mismo. Quien ve «la inacción en la acción» ve en la acción bien hecha el conocimiento del sí-mismo que la acompaña; quien ve «la acción en la inacción» ve que ese conocimiento se cultiva en la acción misma. El verso confirmaría así que el <a class=\"t\" href=\"glosario.html#karma-yoga\" data-t=\"karma-yoga\">yoga de la acción</a> contiene ya el conocimiento y basta para alcanzar la visión del sí-mismo.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "La acción que no ata", "html": "<p>En la tradición <a class=\"t\" href=\"glosario.html#gaudiya\" data-t=\"gaudiya\">gauḍīya</a>, Prabhupāda lee el verso desde la devoción: la acción hecha para Kṛṣṇa, sin buscar el propio provecho, no produce reacción y es, en ese sentido, <em>akarman</em>; quien actúa así es sabio aunque esté plenamente ocupado.</p>", "trad": "gaudiya", "tradNombre": "Vaiṣṇavismo gauḍīya"}, {"titulo": "Lo que importa es desde dónde se actúa", "html": "<p>Muchas lecturas modernas ven aquí el centro del <a class=\"t\" href=\"glosario.html#karma-yoga\" data-t=\"karma-yoga\">yoga de la acción</a>: lo que ata no es el movimiento exterior, sino el apego. Por eso una acción intensa puede ser interiormente quieta, y una abstención aparente puede estar llena de deseo y de agitación. El verso deshace la oposición entre vida activa y vida contemplativa que Arjuna planteaba en <a class=\"vref\" href=\"capitulo-03.html#v1\" data-v=\"3.1\">3.1</a>.</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Quien ve que en la <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a> no actúa el sí-mismo, y que en la <a class=\"t\" href=\"glosario.html#akarma\" data-t=\"akarma\">inacción</a> sigue habiendo acción, ése es, entre los hombres, el que tiene <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a>; ése está unido en <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a> y lleva a cabo toda acción.", "nota": "<p>Explicitación de la lectura del <a class=\"t\" href=\"glosario.html#advaita\" data-t=\"advaita\">Advaita</a>: la «inacción» que se ve en la acción es la del <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">sí-mismo</a>, que nunca actúa aunque el cuerpo y los sentidos obren; y la «acción» que se ve en la inacción es la que sigue habiendo en quien se abstiene creyéndose agente de su quietud.</p>"}, {"html": "Quien ve que la <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a> hecha sin apego es como no actuar, y que dejar de actuar con apego es seguir actuando, ése es, entre los hombres, el que tiene <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a>; ése está unido en <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a> y lleva a cabo toda acción.", "nota": "<p>Explicitación de la lectura del <a class=\"t\" href=\"glosario.html#karma-yoga\" data-t=\"karma-yoga\">yoga de la acción</a>: la acción que no busca su fruto no ata, y en ese sentido equivale a la inacción; en cambio, abstenerse de obrar mientras la mente sigue en los objetos (el «hipócrita» de <a class=\"vref\" href=\"capitulo-03.html#v6\" data-v=\"3.6\">3.6</a>) es una acción que ata. La traducción principal conserva la paradoja del original sin resolverla.</p>"}], "ens": "inaccion-en-la-accion"}, {"n": 19, "hablante": "krsna", "sa": ["यस्य सर्वे समारम्भाः कामसङ्कल्पवर्जिताः ।", "ज्ञानाग्निदग्धकर्माणं तमाहुः पण्डितं बुधाः ॥१९॥"], "iast": ["yasya sarve samārambhāḥ kāma-saṅkalpa-varjitāḥ", "jñānāgni-dagdha-karmāṇaṃ tam āhuḥ paṇḍitaṃ budhāḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Aquel cuyas empresas están todas libres del <a class=\"t\" href=\"glosario.html#kama\" data-t=\"kama\">deseo</a> y del propósito interesado, aquel cuyas acciones ha quemado el fuego del <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a>, a ése los entendidos lo llaman sabio.</span>", "palabras": [{"iast": "yasya", "sa": "यस्य", "gram": "gen. sg. m. pron.", "es": "de quien"}, {"iast": "sarve", "sa": "सर्वे", "gram": "nom. pl. m. adj.", "es": "todas"}, {"iast": "samārambhāḥ", "sa": "समारम्भाः", "gram": "nom. pl. m.", "es": "las empresas, lo que emprende", "analisis": "sam-ā-√rabh (emprender)"}, {"iast": "kāma-saṅkalpa-varjitāḥ", "sa": "कामसङ्कल्पवर्जिताः", "gram": "nom. pl. m. comp.", "es": "libres del deseo y del propósito interesado", "ref": "kama", "analisis": "kāma (deseo) + saṅkalpa (propósito, intención, lo que se imagina obtener) + varjita (privado de, de √vṛj)"}, {"iast": "jñāna-agni-dagdha-karmāṇam", "sa": "ज्ञानाग्निदग्धकर्माणम्", "gram": "ac. sg. m. comp.", "es": "cuyas acciones ha quemado el fuego del conocimiento", "ref": "jnana", "analisis": "jñāna (conocimiento) + agni (fuego) + dagdha (quemado, de √dah) + karman (acción)"}, {"iast": "tam", "sa": "तम्", "gram": "ac. sg. m. pron.", "es": "a ése"}, {"iast": "āhuḥ", "sa": "आहुः", "gram": "3 pl. pf. act.", "es": "llaman", "analisis": "√ah (decir)"}, {"iast": "paṇḍitam", "sa": "पण्डितम्", "gram": "ac. sg. m.", "es": "sabio, docto"}, {"iast": "budhāḥ", "sa": "बुधाः", "gram": "nom. pl. m.", "es": "los entendidos, los despiertos", "analisis": "√budh (despertar, comprender)"}], "nota": "<p><em>Saṅkalpa</em> es el propósito o la representación que precede al deseo: la imagen de lo que se obtendrá. Quien actúa sin ella sigue emprendiendo cosas (<em>samārambha</em>), pero ya no por lo que espera de ellas.</p><p>La imagen del fuego del conocimiento que quema las acciones reaparece y se desarrolla en <a class=\"vref\" href=\"capitulo-04.html#v37\" data-v=\"4.37\">4.37</a>. Nótese el juego entre <em>paṇḍita</em>, «docto», y <em>budha</em>, «el despierto»: son los que entienden quienes reconocen al verdadero sabio.</p>", "interp": [{"titulo": "El fuego del conocimiento", "html": "<p>Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, el fuego que quema las acciones es el conocimiento de que el sí-mismo no actúa. Quien lo ha alcanzado puede seguir realizando acciones, pero éstas ya no dejan huella: se han vuelto, en la terminología del verso anterior, inacción.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "obrar-sin-quedar-atado"}, {"n": 20, "hablante": "krsna", "sa": ["त्यक्त्वा कर्मफलासङ्गं नित्यतृप्तो निराश्रयः ।", "कर्मण्यभिप्रवृत्तोऽपि नैव किञ्चित्करोति सः ॥२०॥"], "iast": ["tyaktvā karma-phalāsaṅgaṃ nitya-tṛpto nirāśrayaḥ", "karmaṇy abhipravṛtto 'pi naiva kiñcit karoti saḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Abandonando el apego al <a class=\"t\" href=\"glosario.html#phala\" data-t=\"phala\">fruto</a> de la acción, siempre satisfecho, sin depender de nada, aunque esté entregado por completo a la <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a>, en verdad no hace nada.</span>", "palabras": [{"iast": "tyaktvā", "sa": "त्यक्त्वा", "gram": "abs.", "es": "abandonando", "analisis": "√tyaj (abandonar, dejar)"}, {"iast": "karma-phala-āsaṅgam", "sa": "कर्मफलासङ्गम्", "gram": "ac. sg. m. comp.", "es": "el apego al fruto de la acción", "ref": "phala", "analisis": "karman (acción) + phala (fruto) + āsaṅga (apego, de ā-√sañj)"}, {"iast": "nitya-tṛptaḥ", "sa": "नित्यतृप्तः", "gram": "nom. sg. m. comp.", "es": "siempre satisfecho", "analisis": "nitya (siempre) + tṛpta (satisfecho, de √tṛp)"}, {"iast": "nirāśrayaḥ", "sa": "निराश्रयः", "gram": "nom. sg. m. adj.", "es": "sin apoyo, sin depender de nada", "analisis": "nis (sin) + āśraya (apoyo, refugio)"}, {"iast": "karmaṇi", "sa": "कर्मणि", "gram": "loc. sg. n.", "es": "en la acción", "ref": "karma"}, {"iast": "abhipravṛttaḥ", "sa": "अभिप्रवृत्तः", "gram": "nom. sg. m. ppp", "es": "entregado por completo", "analisis": "abhi-pra-√vṛt (ponerse a, dedicarse plenamente)"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "aunque"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "en verdad"}, {"iast": "kiñcit", "sa": "किञ्चित्", "gram": "ac. sg. n. pron.", "es": "nada (con la negación)"}, {"iast": "karoti", "sa": "करोति", "gram": "3 sg. pres. act.", "es": "hace", "analisis": "√kṛ (hacer)"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "él"}], "nota": "<p><em>Nirāśraya</em>, «sin apoyo»: el que no busca seguridad en nada, ni en el fruto esperado ni en las cosas. El verso da la otra cara de <a class=\"vref\" href=\"capitulo-04.html#v18\" data-v=\"4.18\">4.18</a>: quien actúa sin apego, aun entregado por completo a la acción, «no hace nada» en el sentido que importa, porque su acción no lo ata.</p>", "interp": [{"titulo": "El sabio que sigue actuando", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> aplica el verso al que alcanzó el conocimiento cuando ya estaba entregado a la acción: en principio debería abandonarla, pues nada tiene ya que lograr con ella; pero, si no puede hacerlo, sigue actuando como antes, por el bien del mundo (<a class=\"vref\" href=\"capitulo-03.html#v20\" data-v=\"3.20\">3.20</a>–<a class=\"vref\" href=\"capitulo-03.html#v26\" data-v=\"3.26\">3.26</a>) o para evitar la censura de las personas cultivadas: como sabe que el sí-mismo no actúa, aunque se entregue a la acción no hace nada.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "obrar-sin-quedar-atado"}, {"n": 21, "hablante": "krsna", "sa": ["निराशीर्यतचित्तात्मा त्यक्तसर्वपरिग्रहः ।", "शारीरं केवलं कर्म कुर्वन्नाप्नोति किल्बिषम् ॥२१॥"], "iast": ["nirāśīr yata-cittātmā tyakta-sarva-parigrahaḥ", "śārīraṃ kevalaṃ karma kurvan nāpnoti kilbiṣam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Libre de esperanzas, con el pensamiento y el cuerpo dominados, habiendo renunciado a toda posesión, realizando sólo la acción del cuerpo, no incurre en falta.</span>", "palabras": [{"iast": "nirāśīḥ", "sa": "निराशीः", "gram": "nom. sg. m. adj.", "es": "libre de esperanzas, sin esperar nada", "analisis": "nis (sin) + āśis (esperanza, deseo)"}, {"iast": "yata-citta-ātmā", "sa": "यतचित्तात्मा", "gram": "nom. sg. m. comp.", "es": "con el pensamiento y el cuerpo dominados", "analisis": "yata (dominado, de √yam) + citta (pensamiento) + ātman (aquí, el cuerpo con sus órganos)"}, {"iast": "tyakta-sarva-parigrahaḥ", "sa": "त्यक्तसर्वपरिग्रहः", "gram": "nom. sg. m. comp.", "es": "que ha renunciado a toda posesión", "analisis": "tyakta (abandonado) + sarva (todo) + parigraha (posesión, lo que uno toma para sí)"}, {"iast": "śārīram", "sa": "शारीरम्", "gram": "ac. sg. n. adj.", "es": "corporal", "analisis": "derivado de śarīra (cuerpo)"}, {"iast": "kevalam", "sa": "केवलम्", "gram": "ac. sg. n. adj.", "es": "sólo, únicamente"}, {"iast": "karma", "sa": "कर्म", "gram": "ac. sg. n.", "es": "la acción", "ref": "karma"}, {"iast": "kurvan", "sa": "कुर्वन्", "gram": "nom. sg. m. part. pres. act.", "es": "realizando", "analisis": "√kṛ (hacer)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "āpnoti", "sa": "आप्नोति", "gram": "3 sg. pres. act.", "es": "incurre en, alcanza", "analisis": "√āp (alcanzar)"}, {"iast": "kilbiṣam", "sa": "किल्बिषम्", "gram": "ac. sg. n.", "es": "falta, culpa"}], "nota": "<p><em>Yata-cittātmā</em>: aquí <em>ātman</em> no es el sí-mismo, sino, como explican <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, el cuerpo con sus órganos (<a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> y <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a> lo entienden como la mente); de ahí «el pensamiento y el cuerpo dominados». <em>Parigraha</em> es todo lo que uno toma para sí: posesiones, pertenencias. <em>Kilbiṣa</em>, «falta, culpa», se traduce como en <a class=\"vref\" href=\"capitulo-03.html#v13\" data-v=\"3.13\">3.13</a>.</p>", "interp": [{"titulo": "El renunciante", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> refiere el verso al renunciante que ha abandonado toda posesión: la «acción del cuerpo» es la mínima necesaria para sostenerlo, y por ella no incurre en ninguna falta que lo devuelva al ciclo de renacimientos.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Libre de esperanzas, con el pensamiento y el cuerpo dominados, habiendo renunciado a toda posesión, realizando sólo la acción necesaria para mantener el cuerpo, no incurre en falta.", "nota": "<p><em>Śārīraṃ kevalaṃ karma</em> admite dos lecturas. Una entiende «la acción que sólo sirve para el cuerpo»: lo indispensable para seguir vivo, como el renunciante que pide limosna para comer. La otra, «la acción hecha sólo con el cuerpo», mientras la mente permanece libre de apego: es la primera glosa de <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> («la que sólo realiza el cuerpo, sin creerse su agente»), y la que <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> discuten y rechazan. <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> pone el acento en <em>kevalam</em>: la sola acción corporal, practicada toda la vida, sin pasar a la disciplina del conocimiento, basta para ver el sí-mismo. La traducción principal conserva la ambigüedad («la acción del cuerpo»).</p>"}], "ens": "obrar-sin-quedar-atado"}, {"n": 22, "hablante": "krsna", "sa": ["यदृच्छालाभसन्तुष्टो द्वन्द्वातीतो विमत्सरः ।", "समः सिद्धावसिद्धौ च कृत्वापि न निबध्यते ॥२२॥"], "iast": ["yadṛcchā-lābha-santuṣṭo dvandvātīto vimatsaraḥ", "samaḥ siddhāv asiddhau ca kṛtvāpi na nibadhyate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Contento con lo que le llega sin buscarlo, más allá de los pares de opuestos, sin envidia, igual ante el éxito y el fracaso, aunque actúe no queda atado.</span>", "palabras": [{"iast": "yadṛcchā-lābha-santuṣṭaḥ", "sa": "यदृच्छालाभसन्तुष्टः", "gram": "nom. sg. m. comp.", "es": "contento con lo que le llega sin buscarlo", "analisis": "yadṛcchā (lo que sucede por sí solo) + lābha (ganancia) + santuṣṭa (contento, de sam-√tuṣ)"}, {"iast": "dvandva-atītaḥ", "sa": "द्वन्द्वातीतः", "gram": "nom. sg. m. comp.", "es": "más allá de los pares de opuestos", "analisis": "dvandva (par de opuestos) + atīta (que ha ido más allá, de ati-√i)"}, {"iast": "vimatsaraḥ", "sa": "विमत्सरः", "gram": "nom. sg. m. adj.", "es": "sin envidia", "analisis": "vi (sin) + matsara (envidia)"}, {"iast": "samaḥ", "sa": "समः", "gram": "nom. sg. m. adj.", "es": "igual, ecuánime", "ref": "samatva"}, {"iast": "siddhau", "sa": "सिद्धौ", "gram": "loc. sg. f.", "es": "en el éxito", "analisis": "siddhi (logro), de √sidh (lograrse)"}, {"iast": "asiddhau", "sa": "असिद्धौ", "gram": "loc. sg. f.", "es": "en el fracaso"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "kṛtvā", "sa": "कृत्वा", "gram": "abs.", "es": "habiendo actuado", "analisis": "√kṛ (hacer)"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "aunque"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "nibadhyate", "sa": "निबध्यते", "gram": "3 sg. pres. pas.", "es": "queda atado", "analisis": "ni-√bandh (atar)"}], "nota": "<p><em>Yadṛcchā</em> es lo que sucede por sí solo, sin haberlo buscado. Los rasgos repiten los del <a class=\"t\" href=\"glosario.html#sthitaprajna\" data-t=\"sthitaprajna\">de sabiduría firme</a> y del yoga ecuánime del capítulo 2: más allá de los pares de opuestos (<a class=\"vref\" href=\"capitulo-02.html#v45\" data-v=\"2.45\">2.45</a>), «igual ante el éxito y el fracaso» (<a class=\"vref\" href=\"capitulo-02.html#v48\" data-v=\"2.48\">2.48</a>). Lo nuevo es la conclusión: «aunque actúe, no queda atado».</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "obrar-sin-quedar-atado"}, {"n": 23, "hablante": "krsna", "sa": ["गतसङ्गस्य मुक्तस्य ज्ञानावस्थितचेतसः ।", "यज्ञायाचरतः कर्म समग्रं प्रविलीयते ॥२३॥"], "iast": ["gata-saṅgasya muktasya jñānāvasthita-cetasaḥ", "yajñāyācarataḥ karma samagraṃ pravilīyate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Para quien ha perdido el apego, para el liberado, cuya mente está asentada en el <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a> y que obra con vistas al <a class=\"t\" href=\"glosario.html#yajna\" data-t=\"yajna\">sacrificio</a>, la <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a> entera se disuelve.</span>", "palabras": [{"iast": "gata-saṅgasya", "sa": "गतसङ्गस्य", "gram": "gen. sg. m. comp.", "es": "de quien ha perdido el apego", "analisis": "gata (ido) + saṅga (apego)"}, {"iast": "muktasya", "sa": "मुक्तस्य", "gram": "gen. sg. m. ppp", "es": "del liberado", "ref": "moksa", "analisis": "√muc (soltar, liberar)"}, {"iast": "jñāna-avasthita-cetasaḥ", "sa": "ज्ञानावस्थितचेतसः", "gram": "gen. sg. m. comp.", "es": "cuya mente está asentada en el conocimiento", "ref": "jnana", "analisis": "jñāna (conocimiento) + avasthita (asentado, de ava-√sthā) + cetas (mente)"}, {"iast": "yajñāya", "sa": "यज्ञाय", "gram": "dat. sg. m.", "es": "por el sacrificio, con vistas al sacrificio", "ref": "yajna"}, {"iast": "ācarataḥ", "sa": "आचरतः", "gram": "gen. sg. m. part. pres. act.", "es": "que actúa", "analisis": "ā-√car (obrar, practicar)"}, {"iast": "karma", "sa": "कर्म", "gram": "nom. sg. n.", "es": "la acción", "ref": "karma"}, {"iast": "samagram", "sa": "समग्रम्", "gram": "nom. sg. n. adj.", "es": "entera, toda"}, {"iast": "pravilīyate", "sa": "प्रविलीयते", "gram": "3 sg. pres. pas.", "es": "se disuelve", "analisis": "pra-vi-√lī (disolverse, fundirse)"}], "nota": "<p>Conclusión de la sección: para quien ha soltado el apego y obra como sacrificio, la acción entera «se disuelve», sin dejar la huella que ata. <em>Yajñāya</em>, «por el sacrificio», enlaza con la doctrina de <a class=\"vref\" href=\"capitulo-03.html#v9\" data-v=\"3.9\">3.9</a> y prepara la gran enumeración de los sacrificios que empieza en <a class=\"vref\" href=\"capitulo-04.html#v24\" data-v=\"4.24\">4.24</a>.</p>", "interp": [{"titulo": "La acción que se disuelve", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> entienden que lo que se destruye es la acción «junto con su fruto» (así glosan <em>samagram</em>, «entera»); <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, que la acción, con sus huellas latentes (<em>vāsanā</em>), se vuelve no-acción: realizada sin apego y como ofrenda, no deja el residuo que, madurando, llevaría a nuevos nacimientos. La imagen prepara la del fuego del conocimiento de <a class=\"vref\" href=\"capitulo-04.html#v37\" data-v=\"4.37\">4.37</a>.</p>", "trad": "vedanta", "tradNombre": "Vedānta clásico"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "obrar-sin-quedar-atado"}, {"n": 24, "hablante": "krsna", "sa": ["ब्रह्मार्पणं ब्रह्म हविर्ब्रह्माग्नौ ब्रह्मणा हुतम् ।", "ब्रह्मैव तेन गन्तव्यं ब्रह्मकर्मसमाधिना ॥२४॥"], "iast": ["brahmārpaṇaṃ brahma havir brahmāgnau brahmaṇā hutam", "brahmaiva tena gantavyaṃ brahma-karma-samādhinā"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">La ofrenda es <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>; brahman es la oblación, que brahman vierte en el fuego de brahman. A brahman ha de llegar quien, en toda acción, permanece absorto en brahman.</span>", "palabras": [{"iast": "brahma-arpaṇam", "sa": "ब्रह्मार्पणम्", "gram": "nom. sg. n. comp.", "es": "la ofrenda es brahman", "ref": "brahman", "analisis": "brahma (brahman) + arpaṇa (el ofrecer, lo ofrecido o aquello con que se ofrece), de ā-√ṛ caus. (entregar)"}, {"iast": "brahma", "sa": "ब्रह्म", "gram": "nom. sg. n.", "es": "brahman", "ref": "brahman"}, {"iast": "haviḥ", "sa": "हविः", "gram": "nom. sg. n.", "es": "la oblación", "analisis": "√hu (verter en el fuego); la oblación, normalmente mantequilla clarificada"}, {"iast": "brahma-agnau", "sa": "ब्रह्माग्नौ", "gram": "loc. sg. m. comp.", "es": "en el fuego de brahman", "ref": "brahman", "analisis": "brahma (brahman) + agni (fuego)"}, {"iast": "brahmaṇā", "sa": "ब्रह्मणा", "gram": "instr. sg. n.", "es": "por brahman", "ref": "brahman"}, {"iast": "hutam", "sa": "हुतम्", "gram": "nom. sg. n. ppp", "es": "vertida, ofrecida en el fuego", "analisis": "√hu (verter en el fuego)"}, {"iast": "brahma", "sa": "ब्रह्म", "gram": "nom. sg. n.", "es": "brahman", "ref": "brahman"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "precisamente"}, {"iast": "tena", "sa": "तेन", "gram": "instr. sg. m. pron.", "es": "por él"}, {"iast": "gantavyam", "sa": "गन्तव्यम्", "gram": "nom. sg. n. gerundivo", "es": "ha de ser alcanzado", "analisis": "√gam (ir)"}, {"iast": "brahma-karma-samādhinā", "sa": "ब्रह्मकर्मसमाधिना", "gram": "instr. sg. m. comp.", "es": "por quien está absorto en la acción que es brahman", "ref": "samadhi", "analisis": "brahma (brahman) + karman (acción) + samādhi (absorción): el que en la acción permanece absorto en brahman"}], "nota": "<p>El verso aplica la palabra brahman a cada elemento del rito védico: <em>arpaṇa</em> (la ofrenda, o aquello con que se ofrece), <em>havis</em> (la oblación), <em>agni</em> (el fuego), el oficiante (<em>brahmaṇā</em>, «por brahman») y la meta. <em>Brahma-karma-samādhi</em> es el que está absorto (<a class=\"t\" href=\"glosario.html#samadhi\" data-t=\"samadhi\"><em>samādhi</em></a>) en la acción que es brahman: quien en todo lo que hace ve brahman.</p><p>Es uno de los versos más recitados de la Gītā: muchos lo dicen como bendición antes de comer, y la comida se vuelve así una ofrenda.</p>", "interp": [{"titulo": "Todo es brahman", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lee el verso como la visión del que conoce: para quien sabe que todo es brahman, el instrumento, la oblación, el fuego, el oficiante y el fruto del sacrificio son brahman, y su acción, vista así, deja de ser acción. El verso no describe un rito, sino la manera de ver de quien ha alcanzado el conocimiento; por eso alaba el conocimiento como el verdadero sacrificio.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Una bendición de la mesa", "html": "<p>El verso se recita antes de comer en muchos āśrams, escuelas y casas de la India, a veces junto con <a class=\"vref\" href=\"capitulo-15.html#v14\" data-v=\"15.14\">15.14</a>, donde Kṛṣṇa se dice el fuego que digiere el alimento en los seres. Comer se vuelve así una ofrenda, y el alimento, lo que queda del sacrificio (<a class=\"vref\" href=\"capitulo-03.html#v13\" data-v=\"3.13\">3.13</a>).</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Brahman es el instrumento con que se ofrece; brahman, la oblación vertida por brahman en el fuego que es brahman. A brahman llega quien ve brahman en la acción.", "nota": "<p><em>Arpaṇa</em> puede ser el acto de ofrecer, lo ofrecido o aquello con que se ofrece: el cucharón del rito. Los comentaristas advaitas lo entienden como el instrumento, y así cada uno de los factores del sacrificio —instrumento, oblación, fuego, oficiante y meta— es brahman para quien conoce. <em>Brahma-karma-samādhi</em> admite también dos matices: el que «está absorto en la acción que es brahman» o el que «ve brahman en la acción».</p>"}], "ens": "ver-brahman-en-la-accion"}, {"n": 25, "hablante": "krsna", "sa": ["दैवमेवापरे यज्ञं योगिनः पर्युपासते ।", "ब्रह्माग्नावपरे यज्ञं यज्ञेनैवोपजुह्वति ॥२५॥"], "iast": ["daivam evāpare yajñaṃ yoginaḥ paryupāsate", "brahmāgnāv apare yajñaṃ yajñenaivopajuhvati"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Algunos yoguis celebran el sacrificio a los dioses; otros ofrecen el sacrificio mismo, por medio del sacrificio, en el fuego de <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>.</span>", "palabras": [{"iast": "daivam", "sa": "दैवम्", "gram": "ac. sg. m. adj.", "es": "dirigido a los dioses", "ref": "deva", "analisis": "derivado de deva (dios)"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "precisamente"}, {"iast": "apare", "sa": "अपरे", "gram": "nom. pl. m. pron.", "es": "algunos, otros"}, {"iast": "yajñam", "sa": "यज्ञम्", "gram": "ac. sg. m.", "es": "el sacrificio", "ref": "yajna", "analisis": "√yaj (sacrificar, honrar)"}, {"iast": "yoginaḥ", "sa": "योगिनः", "gram": "nom. pl. m.", "es": "yoguis", "ref": "yoga", "analisis": "derivado de yoga"}, {"iast": "paryupāsate", "sa": "पर्युपासते", "gram": "3 pl. pres. med.", "es": "practican, celebran", "analisis": "pari-upa-√ās (sentarse junto a, servir, honrar)"}, {"iast": "brahma-agnau", "sa": "ब्रह्माग्नौ", "gram": "loc. sg. m. comp.", "es": "en el fuego de brahman", "ref": "brahman", "analisis": "brahma (brahman) + agni (fuego)"}, {"iast": "apare", "sa": "अपरे", "gram": "nom. pl. m. pron.", "es": "otros"}, {"iast": "yajñam", "sa": "यज्ञम्", "gram": "ac. sg. m.", "es": "el sacrificio", "ref": "yajna"}, {"iast": "yajñena", "sa": "यज्ञेन", "gram": "instr. sg. m.", "es": "por medio del sacrificio", "ref": "yajna"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "precisamente, mismo"}, {"iast": "upajuhvati", "sa": "उपजुह्वति", "gram": "3 pl. pres. act.", "es": "ofrecen, vierten en el fuego", "analisis": "upa-√hu (verter como oblación)"}], "nota": "<p><em>Daiva yajña</em> es el sacrificio a los <a class=\"t\" href=\"glosario.html#deva\" data-t=\"deva\">dioses</a> del rito védico. La segunda mitad, «otros ofrecen el sacrificio por medio del sacrificio en el fuego de brahman», es de las expresiones más oscuras del capítulo; la traducción la deja tan abierta como el original. Véase la interpretación.</p>", "interp": [{"titulo": "Ofrecerse a sí mismo en brahman", "html": "<p>Los comentaristas advaitas entienden la segunda mitad como la ofrenda del propio yo, tal como aparece limitado por el cuerpo y la mente, en el fuego de brahman: reconocer que el sí-mismo individual no es otro que brahman. El verso opondría así dos sacrificios: el rito tradicional a los dioses y el conocimiento, en el que lo que se ofrece es la propia individualidad.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "formas-del-sacrificio"}, {"n": 26, "hablante": "krsna", "sa": ["श्रोत्रादीनीन्द्रियाण्यन्ये संयमाग्निषु जुह्वति ।", "शब्दादीन्विषयानन्य इन्द्रियाग्निषु जुह्वति ॥२६॥"], "iast": ["śrotrādīnīndriyāṇy anye saṃyamāgniṣu juhvati", "śabdādīn viṣayān anya indriyāgniṣu juhvati"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Otros ofrecen el oído y los demás <a class=\"t\" href=\"glosario.html#indriya\" data-t=\"indriya\">sentidos</a> en los fuegos del dominio de sí; otros ofrecen el sonido y los demás <a class=\"t\" href=\"glosario.html#visaya\" data-t=\"visaya\">objetos de los sentidos</a> en los fuegos de los sentidos.</span>", "palabras": [{"iast": "śrotra-ādīni", "sa": "श्रोत्रादीनि", "gram": "ac. pl. n. comp.", "es": "el oído y los demás", "analisis": "śrotra (oído) + ādi (lo que empieza por)"}, {"iast": "indriyāṇi", "sa": "इन्द्रियाणि", "gram": "ac. pl. n.", "es": "los sentidos", "ref": "indriya"}, {"iast": "anye", "sa": "अन्ये", "gram": "nom. pl. m. pron.", "es": "otros"}, {"iast": "saṃyama-agniṣu", "sa": "संयमाग्निषु", "gram": "loc. pl. m. comp.", "es": "en los fuegos del dominio de sí", "analisis": "saṃyama (contención, dominio), de sam-√yam (sujetar) + agni (fuego)"}, {"iast": "juhvati", "sa": "जुह्वति", "gram": "3 pl. pres. act.", "es": "ofrecen, vierten en el fuego", "analisis": "√hu (verter como oblación)"}, {"iast": "śabda-ādīn", "sa": "शब्दादीन्", "gram": "ac. pl. m. comp.", "es": "el sonido y los demás", "analisis": "śabda (sonido) + ādi (lo que empieza por)"}, {"iast": "viṣayān", "sa": "विषयान्", "gram": "ac. pl. m.", "es": "los objetos de los sentidos", "ref": "visaya"}, {"iast": "anye", "sa": "अन्ये", "gram": "nom. pl. m. pron.", "es": "otros"}, {"iast": "indriya-agniṣu", "sa": "इन्द्रियाग्निषु", "gram": "loc. pl. m. comp.", "es": "en los fuegos de los sentidos", "ref": "indriya", "analisis": "indriya (sentido) + agni (fuego)"}, {"iast": "juhvati", "sa": "जुह्वति", "gram": "3 pl. pres. act.", "es": "ofrecen"}], "nota": "<p><em>Saṃyama</em>, «contención, dominio», tiene aquí su sentido general. Los <em>Yoga-sūtra</em> usarán la misma palabra, en sentido técnico, para la unión de concentración, meditación y absorción (3.4).</p>", "interp": [{"titulo": "Retirarse o moverse entre los objetos", "html": "<p>Los dos sacrificios de este verso corresponden a dos disciplinas que la Gītā ya conoce: retirar los sentidos de sus objetos, como la tortuga sus miembros (<a class=\"vref\" href=\"capitulo-02.html#v58\" data-v=\"2.58\">2.58</a>), y moverse entre los objetos con los sentidos dominados, sin atracción ni aversión (<a class=\"vref\" href=\"capitulo-02.html#v64\" data-v=\"2.64\">2.64</a>). En el primero se ofrecen los sentidos en el fuego del dominio de sí; en el segundo, los objetos en el fuego de los sentidos: se los recibe sin apropiarse de ellos.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "formas-del-sacrificio"}, {"n": 27, "hablante": "krsna", "sa": ["सर्वाणीन्द्रियकर्माणि प्राणकर्माणि चापरे ।", "आत्मसंयमयोगाग्नौ जुह्वति ज्ञानदीपिते ॥२७॥"], "iast": ["sarvāṇīndriya-karmāṇi prāṇa-karmāṇi cāpare", "ātma-saṃyama-yogāgnau juhvati jñāna-dīpite"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Otros ofrecen todas las acciones de los <a class=\"t\" href=\"glosario.html#indriya\" data-t=\"indriya\">sentidos</a> y las del <a class=\"t\" href=\"glosario.html#prana\" data-t=\"prana\">aliento vital</a> en el fuego del <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a> del dominio de sí, encendido por el <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a>.</span>", "palabras": [{"iast": "sarvāṇi", "sa": "सर्वाणि", "gram": "ac. pl. n. adj.", "es": "todas"}, {"iast": "indriya-karmāṇi", "sa": "इन्द्रियकर्माणि", "gram": "ac. pl. n. comp.", "es": "las acciones de los sentidos", "ref": "indriya", "analisis": "indriya (sentido) + karman (acción)"}, {"iast": "prāṇa-karmāṇi", "sa": "प्राणकर्माणि", "gram": "ac. pl. n. comp.", "es": "las acciones del aliento vital", "ref": "prana", "analisis": "prāṇa (aliento vital) + karman (acción)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "apare", "sa": "अपरे", "gram": "nom. pl. m. pron.", "es": "otros"}, {"iast": "ātma-saṃyama-yoga-agnau", "sa": "आत्मसंयमयोगाग्नौ", "gram": "loc. sg. m. comp.", "es": "en el fuego del yoga del dominio de sí", "ref": "yoga", "analisis": "ātman (uno mismo) + saṃyama (dominio) + yoga + agni (fuego)"}, {"iast": "juhvati", "sa": "जुह्वति", "gram": "3 pl. pres. act.", "es": "ofrecen"}, {"iast": "jñāna-dīpite", "sa": "ज्ञानदीपिते", "gram": "loc. sg. m. comp. ppp", "es": "encendido por el conocimiento", "ref": "jnana", "analisis": "jñāna (conocimiento) + dīpita (encendido), de √dīp caus. (hacer arder)"}], "nota": "<p><em>Ātma-saṃyama-yoga</em>, «el yoga del dominio de sí», es casi el título que la tradición da al capítulo 6, donde se desarrolla esta disciplina.</p>", "interp": [{"titulo": "El fuego encendido por el conocimiento", "html": "<p>Aquí el sacrificio es completamente interior: toda la actividad de los sentidos y del aliento se ofrece en el dominio de sí, que es un fuego, pero un fuego que sólo arde si lo enciende el conocimiento. Para la tradición vedántica, la concentración sin discernimiento no basta: lo que consume las acciones es saber quién actúa (<a class=\"vref\" href=\"capitulo-04.html#v37\" data-v=\"4.37\">4.37</a>).</p>", "trad": "vedanta", "tradNombre": "Vedānta clásico"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "formas-del-sacrificio"}, {"n": 28, "hablante": "krsna", "sa": ["द्रव्ययज्ञास्तपोयज्ञा योगयज्ञास्तथापरे ।", "स्वाध्यायज्ञानयज्ञाश्च यतयः संशितव्रताः ॥२८॥"], "iast": ["dravya-yajñās tapo-yajñā yoga-yajñās tathāpare", "svādhyāya-jñāna-yajñāś ca yatayaḥ saṃśita-vratāḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Así, unos ofrecen en sacrificio sus bienes; otros, su <a class=\"t\" href=\"glosario.html#tapas\" data-t=\"tapas\">austeridad</a>; otros, el <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a>; y otros, ascetas de votos rigurosos, el <a class=\"t\" href=\"glosario.html#svadhyaya\" data-t=\"svadhyaya\">estudio de los textos sagrados</a> y el conocimiento.</span>", "palabras": [{"iast": "dravya-yajñāḥ", "sa": "द्रव्ययज्ञाः", "gram": "nom. pl. m. comp.", "es": "los que sacrifican sus bienes", "ref": "yajna", "analisis": "dravya (bienes, sustancias) + yajña (sacrificio): «cuyo sacrificio son los bienes»"}, {"iast": "tapo-yajñāḥ", "sa": "तपोयज्ञाः", "gram": "nom. pl. m. comp.", "es": "los que hacen de la austeridad su sacrificio", "ref": "tapas", "analisis": "tapas (austeridad) + yajña (sacrificio)"}, {"iast": "yoga-yajñāḥ", "sa": "योगयज्ञाः", "gram": "nom. pl. m. comp.", "es": "los que hacen del yoga su sacrificio", "ref": "yoga", "analisis": "yoga + yajña (sacrificio)"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "así, del mismo modo"}, {"iast": "apare", "sa": "अपरे", "gram": "nom. pl. m. pron.", "es": "otros"}, {"iast": "svādhyāya-jñāna-yajñāḥ", "sa": "स्वाध्यायज्ञानयज्ञाः", "gram": "nom. pl. m. comp.", "es": "los que hacen del estudio y del conocimiento su sacrificio", "ref": "svadhyaya", "analisis": "svādhyāya (estudio de los textos sagrados) + jñāna (conocimiento) + yajña (sacrificio)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "yatayaḥ", "sa": "यतयः", "gram": "nom. pl. m.", "es": "ascetas", "analisis": "yati, de √yat (esforzarse): «el que se esfuerza»"}, {"iast": "saṃśita-vratāḥ", "sa": "संशितव्रताः", "gram": "nom. pl. m. comp.", "es": "de votos rigurosos", "analisis": "saṃśita (afilado), de sam-√śo (afilar) + vrata (voto)"}], "nota": "<p><em>Dravya-yajña</em>: el sacrificio que se hace con bienes, sean ofrendas rituales, limosnas u obras en beneficio de otros. <em>Yati</em>, «el que se esfuerza», es un nombre del asceta. <em>Saṃśita-vrata</em>: literalmente, «de votos afilados», es decir, rigurosos.</p>", "interp": [{"titulo": "Una lista de prácticas", "html": "<p>La enumeración recoge las prácticas religiosas de la época —dar los propios bienes, las austeridades, el yoga, la recitación del Veda— y las presenta todas como sacrificio. Es una manera de ampliar la idea de <a class=\"t\" href=\"glosario.html#yajna\" data-t=\"yajna\">sacrificio</a> (<a class=\"vref\" href=\"capitulo-03.html#v9\" data-v=\"3.9\">3.9</a>) sin negar el rito: cualquier práctica lo es si se hace como ofrenda. El último compuesto, <em>svādhyāya-jñāna-yajñāḥ</em>, puede entenderse como un solo grupo, el de quienes ofrecen el estudio y el conocimiento, o como dos.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "formas-del-sacrificio"}, {"n": 29, "hablante": "krsna", "sa": ["अपाने जुह्वति प्राणं प्राणेऽपानं तथापरे ।", "प्राणापानगती रुद्ध्वा प्राणायामपरायणाः ॥२९॥"], "iast": ["apāne juhvati prāṇaṃ prāṇe 'pānaṃ tathāpare", "prāṇāpāna-gatī ruddhvā prāṇāyāma-parāyaṇāḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Otros ofrecen el <a class=\"t\" href=\"glosario.html#prana\" data-t=\"prana\">prāṇa</a> en el apāna, y el apāna en el prāṇa; y otros, entregados al <a class=\"t\" href=\"glosario.html#pranayama\" data-t=\"pranayama\">control del aliento</a>, detienen el curso de ambos alientos.</span>", "palabras": [{"iast": "apāne", "sa": "अपाने", "gram": "loc. sg. m.", "es": "en la espiración", "ref": "prana", "analisis": "apa-√an (respirar hacia fuera o hacia abajo)"}, {"iast": "juhvati", "sa": "जुह्वति", "gram": "3 pl. pres. act.", "es": "ofrecen"}, {"iast": "prāṇam", "sa": "प्राणम्", "gram": "ac. sg. m.", "es": "la inspiración", "ref": "prana", "analisis": "pra-√an (respirar)"}, {"iast": "prāṇe", "sa": "प्राणे", "gram": "loc. sg. m.", "es": "en la inspiración", "ref": "prana"}, {"iast": "apānam", "sa": "अपानम्", "gram": "ac. sg. m.", "es": "la espiración", "ref": "prana"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "del mismo modo"}, {"iast": "apare", "sa": "अपरे", "gram": "nom. pl. m. pron.", "es": "otros"}, {"iast": "prāṇa-apāna-gatī", "sa": "प्राणापानगती", "gram": "ac. du. f. comp.", "es": "el curso de la inspiración y la espiración", "ref": "prana", "analisis": "prāṇa + apāna + gati (curso, movimiento)"}, {"iast": "ruddhvā", "sa": "रुद्ध्वा", "gram": "abs.", "es": "deteniendo", "analisis": "√rudh (detener, contener)"}, {"iast": "prāṇāyāma-parāyaṇāḥ", "sa": "प्राणायामपरायणाः", "gram": "nom. pl. m. comp.", "es": "entregados al control del aliento", "ref": "pranayama", "analisis": "prāṇāyāma (control del aliento) + parāyaṇa (dedicado a, cuyo fin supremo es)"}], "nota": "<p><em>Prāṇa</em> y <em>apāna</em> son los dos alientos principales. Esta edición los deja sin traducir porque los textos no coinciden en cuál es cuál (véanse las alternativas y la ficha <a class=\"t\" href=\"glosario.html#prana\" data-t=\"prana\">prāṇa</a>): para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, el curso del <em>prāṇa</em> es la salida del aire, y el del <em>apāna</em>, la entrada; <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> hace del <em>prāṇa</em> el aliento que sube y del <em>apāna</em> el que baja; y muchas lecturas modernas ligadas al yoga asocian el <em>prāṇa</em> a la inspiración.</p><p>Casi todos los comentaristas (<a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>) ven en el verso las tres fases del <a class=\"t\" href=\"glosario.html#pranayama\" data-t=\"pranayama\">control del aliento</a>: llenar los pulmones (<em>pūraka</em>), vaciarlos (<em>recaka</em>) y retener el aire (<em>kumbhaka</em>); Madhusūdana, siguiendo a Patañjali, distingue además una retención tras inspirar, otra tras espirar y una cuarta. <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>, en cambio, refiere todo el verso a la retención.</p>", "interp": [{"titulo": "Yoga y control del aliento", "html": "<p>El verso describe una técnica respiratoria que el yoga clásico codificará. Los <em>Yoga-sūtra</em> de Patañjali definen el control del aliento como la interrupción del curso de la inspiración y la espiración (2.49), muy cerca de la expresión de la Gītā, <em>prāṇāpāna-gatī ruddhvā</em>, «deteniendo el curso de ambos alientos». Es uno de los indicios de que la Gītā conoce prácticas de yoga que después se sistematizarían.</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Otros ofrecen la espiración en la inspiración, y la inspiración en la espiración; y otros, entregados al control del aliento, detienen el curso de ambas.", "nota": "<p>Con <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, para quienes el curso del <em>prāṇa</em> es la salida del aire por la boca y la nariz, y el del <em>apāna</em>, el movimiento contrario. Ofrecer el <em>prāṇa</em> en el <em>apāna</em> es entonces llenar los pulmones (<em>pūraka</em>), y ofrecer el <em>apāna</em> en el <em>prāṇa</em>, vaciarlos (<em>recaka</em>).</p>"}, {"html": "Otros ofrecen la inspiración en la espiración, y la espiración en la inspiración; y otros, entregados al control del aliento, detienen el curso de ambas.", "nota": "<p>Con la correspondencia frecuente en el yoga moderno, que asocia el <em>prāṇa</em> al aire que entra y el <em>apāna</em> al que sale; así lo entiende también la traducción inglesa de Ādidevānanda del comentario de <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, aunque el sánscrito de éste no lo precisa.</p>"}], "ens": "formas-del-sacrificio"}, {"n": 30, "hablante": "krsna", "sa": ["अपरे नियताहाराः प्राणान्प्राणेषु जुह्वति ।", "सर्वेऽप्येते यज्ञविदो यज्ञक्षपितकल्मषाः ॥३०॥"], "iast": ["apare niyatāhārāḥ prāṇān prāṇeṣu juhvati", "sarve 'py ete yajña-vido yajña-kṣapita-kalmaṣāḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Otros, regulando su alimento, ofrecen los <a class=\"t\" href=\"glosario.html#prana\" data-t=\"prana\">alientos vitales</a> en los alientos vitales. Todos ellos conocen el <a class=\"t\" href=\"glosario.html#yajna\" data-t=\"yajna\">sacrificio</a>, y por el sacrificio han borrado sus impurezas.</span>", "palabras": [{"iast": "apare", "sa": "अपरे", "gram": "nom. pl. m. pron.", "es": "otros"}, {"iast": "niyata-āhārāḥ", "sa": "नियताहाराः", "gram": "nom. pl. m. comp.", "es": "que regulan su alimento", "analisis": "niyata (regulado, restringido), de ni-√yam + āhāra (alimento)"}, {"iast": "prāṇān", "sa": "प्राणान्", "gram": "ac. pl. m.", "es": "los alientos vitales", "ref": "prana"}, {"iast": "prāṇeṣu", "sa": "प्राणेषु", "gram": "loc. pl. m.", "es": "en los alientos vitales", "ref": "prana"}, {"iast": "juhvati", "sa": "जुह्वति", "gram": "3 pl. pres. act.", "es": "ofrecen"}, {"iast": "sarve", "sa": "सर्वे", "gram": "nom. pl. m. adj.", "es": "todos"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "también"}, {"iast": "ete", "sa": "एते", "gram": "nom. pl. m. pron.", "es": "estos"}, {"iast": "yajña-vidaḥ", "sa": "यज्ञविदः", "gram": "nom. pl. m. comp.", "es": "conocedores del sacrificio", "ref": "yajna", "analisis": "yajña (sacrificio) + vid (que conoce)"}, {"iast": "yajña-kṣapita-kalmaṣāḥ", "sa": "यज्ञक्षपितकल्मषाः", "gram": "nom. pl. m. comp.", "es": "cuyas impurezas ha destruido el sacrificio", "ref": "yajna", "analisis": "yajña (sacrificio) + kṣapita (destruido), de √kṣi caus. + kalmaṣa (mancha, impureza)"}], "nota": "<p><em>Niyatāhāra</em>: «de alimento regulado o restringido». <em>Kalmaṣa</em>: «mancha, impureza».</p>", "interp": [{"titulo": "Regular el alimento", "html": "<p>Los comentaristas entienden <em>niyatāhārāḥ</em> como quienes reducen o regulan su alimento, pero explican de distinto modo la ofrenda de los alientos en los alientos. Para <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a> es el efecto de ese ayuno: al secarse los alientos, se funden unos en otros; para <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, lo que se ofrece son las funciones de los sentidos, que se apagan al debilitarse éstos con el ayuno; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lo entiende como el dominio de uno de los alientos vitales, en el que se hace entrar a los demás; y <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, como la retención del aliento (<em>kumbhaka</em>), en la que, según Madhusūdana, se disuelven los sentidos. Es la forma de sacrificio más ascética de la lista, y el verso la iguala a las demás: lo que cuenta no es la práctica, sino que se haga como sacrificio. La Gītā recomendará en otro lugar la moderación, no el ayuno extremo (<a class=\"vref\" href=\"capitulo-06.html#v16\" data-v=\"6.16\">6.16</a>–<a class=\"vref\" href=\"capitulo-06.html#v17\" data-v=\"6.17\">6.17</a>).</p>", "trad": "vedanta", "tradNombre": "Vedānta clásico"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "formas-del-sacrificio"}, {"n": 31, "hablante": "krsna", "sa": ["यज्ञशिष्टामृतभुजो यान्ति ब्रह्म सनातनम् ।", "नायं लोकोऽस्त्ययज्ञस्य कुतोऽन्यः कुरुसत्तम ॥३१॥"], "iast": ["yajña-śiṣṭāmṛta-bhujo yānti brahma sanātanam", "nāyaṃ loko 'sty ayajñasya kuto 'nyaḥ kuru-sattama"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Los que comen el néctar que queda del <a class=\"t\" href=\"glosario.html#yajna\" data-t=\"yajna\">sacrificio</a> alcanzan el <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a> eterno. Ni siquiera este mundo es para quien no sacrifica; ¿cómo lo sería el otro, oh <a class=\"t\" href=\"glosario.html#kurusattama\" data-t=\"kurusattama\">Kurusattama</a>?</span>", "palabras": [{"iast": "yajña-śiṣṭa-amṛta-bhujaḥ", "sa": "यज्ञशिष्टामृतभुजः", "gram": "nom. pl. m. comp.", "es": "los que comen el néctar que queda del sacrificio", "ref": "yajna", "analisis": "yajña (sacrificio) + śiṣṭa (lo que queda), de √śiṣ + amṛta (néctar, lo inmortal) + bhuj (que come)"}, {"iast": "yānti", "sa": "यान्ति", "gram": "3 pl. pres. act.", "es": "van, alcanzan", "analisis": "√yā (ir)"}, {"iast": "brahma", "sa": "ब्रह्म", "gram": "ac. sg. n.", "es": "brahman", "ref": "brahman"}, {"iast": "sanātanam", "sa": "सनातनम्", "gram": "ac. sg. n. adj.", "es": "eterno"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "ayam", "sa": "अयम्", "gram": "nom. sg. m. pron.", "es": "este"}, {"iast": "lokaḥ", "sa": "लोकः", "gram": "nom. sg. m.", "es": "mundo"}, {"iast": "asti", "sa": "अस्ति", "gram": "3 sg. pres. act.", "es": "es, hay", "analisis": "√as (ser)"}, {"iast": "ayajñasya", "sa": "अयज्ञस्य", "gram": "gen. sg. m.", "es": "para el que no sacrifica", "ref": "yajna", "analisis": "a- (no) + yajña (sacrificio)"}, {"iast": "kutaḥ", "sa": "कुतः", "gram": "ind.", "es": "¿cómo?, ¿de dónde?"}, {"iast": "anyaḥ", "sa": "अन्यः", "gram": "nom. sg. m. pron.", "es": "el otro"}, {"iast": "kuru-sattama", "sa": "कुरुसत्तम", "gram": "voc. sg. m. comp.", "es": "oh el mejor de los Kurus", "ref": "kurusattama", "analisis": "kuru (los Kurus) + sattama (el mejor), superlativo de sat"}], "nota": "<p><em>Amṛta</em>, «inmortal», es también el néctar de los dioses, la bebida de la inmortalidad. El «otro» mundo es el que se espera después de la muerte.</p>", "interp": [{"titulo": "El néctar de los restos", "html": "<p>Lo que en <a class=\"vref\" href=\"capitulo-03.html#v13\" data-v=\"3.13\">3.13</a> era «lo que queda del sacrificio» es aquí néctar, <em>amṛta</em>, la bebida de la inmortalidad. Quien sólo come lo que antes ha ofrecido vive de algo que ya no es suyo, y eso lo conduce a lo eterno. La segunda mitad vuelve al argumento de <a class=\"vref\" href=\"capitulo-03.html#v16\" data-v=\"3.16\">3.16</a>: sin sacrificio no hay vida que valga ni siquiera en este mundo.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "formas-del-sacrificio"}, {"n": 32, "hablante": "krsna", "sa": ["एवं बहुविधा यज्ञा वितता ब्रह्मणो मुखे ।", "कर्मजान्विद्धि तान्सर्वानेवं ज्ञात्वा विमोक्ष्यसे ॥३२॥"], "iast": ["evaṃ bahu-vidhā yajñā vitatā brahmaṇo mukhe", "karma-jān viddhi tān sarvān evaṃ jñātvā vimokṣyase"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Así, muchas clases de <a class=\"t\" href=\"glosario.html#yajna\" data-t=\"yajna\">sacrificio</a> están desplegadas en la boca de <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>. Sabe que todas nacen de la <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a>; sabiéndolo, te liberarás.</span>", "palabras": [{"iast": "evam", "sa": "एवम्", "gram": "ind.", "es": "así"}, {"iast": "bahu-vidhāḥ", "sa": "बहुविधाः", "gram": "nom. pl. m. comp.", "es": "de muchas clases", "analisis": "bahu (mucho) + vidhā (clase, modo)"}, {"iast": "yajñāḥ", "sa": "यज्ञाः", "gram": "nom. pl. m.", "es": "sacrificios", "ref": "yajna"}, {"iast": "vitatāḥ", "sa": "वितताः", "gram": "nom. pl. m. ppp", "es": "desplegados, extendidos", "analisis": "vi-√tan (extender)"}, {"iast": "brahmaṇaḥ", "sa": "ब्रह्मणः", "gram": "gen. sg. n.", "es": "de brahman", "ref": "brahman"}, {"iast": "mukhe", "sa": "मुखे", "gram": "loc. sg. n.", "es": "en la boca, a la entrada"}, {"iast": "karma-jān", "sa": "कर्मजान्", "gram": "ac. pl. m. comp.", "es": "nacidos de la acción", "ref": "karma", "analisis": "karman (acción) + ja (nacido), de √jan"}, {"iast": "viddhi", "sa": "विद्धि", "gram": "2 sg. impv. act.", "es": "sabe", "analisis": "√vid (saber)"}, {"iast": "tān", "sa": "तान्", "gram": "ac. pl. m. pron.", "es": "a ellos"}, {"iast": "sarvān", "sa": "सर्वान्", "gram": "ac. pl. m. adj.", "es": "todos"}, {"iast": "evam", "sa": "एवम्", "gram": "ind.", "es": "así"}, {"iast": "jñātvā", "sa": "ज्ञात्वा", "gram": "abs.", "es": "sabiéndolo", "analisis": "√jñā (conocer)"}, {"iast": "vimokṣyase", "sa": "विमोक्ष्यसे", "gram": "2 sg. fut. med.", "es": "serás liberado", "ref": "moksa", "analisis": "vi-√muc (soltar, liberar)"}], "nota": "<p><em>Brahmaṇo mukhe</em>: literalmente, «en la boca (o a la entrada) de brahman». Admite dos lecturas: «expuestos en el Veda» o «desplegados ante brahman, que los recibe»; véanse las alternativas.</p>", "interp": [{"titulo": "Saber que los sacrificios nacen de la acción", "html": "<p>Para los comentaristas advaitas, lo que libera es saber que todos esos sacrificios nacen de la acción, es decir, de la actividad del cuerpo, la palabra y la mente, y no del sí-mismo, que no actúa. Quien lo sabe deja de identificarse con el que sacrifica, y esa visión es la liberación.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Así, muchas clases de sacrificio están expuestas en el Veda. Sabe que todas nacen de la acción; sabiéndolo, te liberarás.", "nota": "<p><em>Brahmaṇo mukhe</em> es literalmente «en la boca (o a la entrada) de brahman». Si brahman es aquí el Veda, como en <a class=\"vref\" href=\"capitulo-03.html#v15\" data-v=\"3.15\">3.15</a> según <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, el sentido es «expuestos en el Veda», es decir, prescritos por él. Si es el absoluto, la imagen es la del fuego, boca de los dioses por la que se ofrece: los sacrificios se vierten en brahman.</p>"}], "ens": "formas-del-sacrificio"}, {"n": 33, "hablante": "krsna", "sa": ["श्रेयान्द्रव्यमयाद्यज्ञाज्ज्ञानयज्ञः परन्तप ।", "सर्वं कर्माखिलं पार्थ ज्ञाने परिसमाप्यते ॥३३॥"], "iast": ["śreyān dravya-mayād yajñāj jñāna-yajñaḥ parantapa", "sarvaṃ karmākhilaṃ pārtha jñāne parisamāpyate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Mejor que el sacrificio de bienes materiales es el <a class=\"t\" href=\"glosario.html#jnana-yajna\" data-t=\"jnana-yajna\">sacrificio del conocimiento</a>, oh <a class=\"t\" href=\"glosario.html#parantapa\" data-t=\"parantapa\">Parantapa</a>: toda <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a>, sin excepción, culmina en el <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a>, oh <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a>.</span>", "palabras": [{"iast": "śreyān", "sa": "श्रेयान्", "gram": "nom. sg. m. adj.", "es": "mejor, superior", "analisis": "comparativo (śreyas) de praśasya (excelente), de la raíz de śrī"}, {"iast": "dravya-mayāt", "sa": "द्रव्यमयात्", "gram": "abl. sg. m. comp.", "es": "que el hecho de bienes materiales", "analisis": "dravya (bienes, sustancias) + maya (hecho de)"}, {"iast": "yajñāt", "sa": "यज्ञात्", "gram": "abl. sg. m.", "es": "que el sacrificio", "ref": "yajna"}, {"iast": "jñāna-yajñaḥ", "sa": "ज्ञानयज्ञः", "gram": "nom. sg. m. comp.", "es": "el sacrificio del conocimiento", "ref": "jnana-yajna", "analisis": "jñāna (conocimiento) + yajña (sacrificio)"}, {"iast": "parantapa", "sa": "परन्तप", "gram": "voc. sg. m.", "es": "oh Parantapa", "ref": "parantapa"}, {"iast": "sarvam", "sa": "सर्वम्", "gram": "nom. sg. n. adj.", "es": "toda"}, {"iast": "karma", "sa": "कर्म", "gram": "nom. sg. n.", "es": "la acción", "ref": "karma"}, {"iast": "akhilam", "sa": "अखिलम्", "gram": "nom. sg. n. adj.", "es": "entera, sin resto"}, {"iast": "pārtha", "sa": "पार्थ", "gram": "voc. sg. m.", "es": "oh Pārtha", "ref": "partha"}, {"iast": "jñāne", "sa": "ज्ञाने", "gram": "loc. sg. n.", "es": "en el conocimiento", "ref": "jnana"}, {"iast": "parisamāpyate", "sa": "परिसमाप्यते", "gram": "3 sg. pres. pas.", "es": "culmina, llega a su término", "analisis": "pari-sam-√āp (alcanzar, completar)"}], "nota": "<p><em>Parisamāpyate</em>: «se completa, llega a su término». El verso cierra la enumeración de sacrificios y prepara el elogio del conocimiento que sigue (<a class=\"vref\" href=\"capitulo-04.html#v34\" data-v=\"4.34\">4.34</a>–<a class=\"vref\" href=\"capitulo-04.html#v38\" data-v=\"4.38\">4.38</a>).</p>", "interp": [{"titulo": "Toda acción culmina en el conocimiento", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lee el verso a la luz de su doctrina: el fruto de todos los sacrificios queda contenido en el conocimiento, como las jugadas menores en la jugada ganadora del juego de dados, imagen que toma de la <em>Chāndogya Upaniṣad</em> (4.1.4). Por eso el sacrificio del conocimiento es superior: no produce un fruto más, sino que es el fin al que tienden todos.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "sacrificio-del-conocimiento"}, {"n": 34, "hablante": "krsna", "sa": ["तद्विद्धि प्रणिपातेन परिप्रश्नेन सेवया ।", "उपदेक्ष्यन्ति ते ज्ञानं ज्ञानिनस्तत्त्वदर्शिनः ॥३४॥"], "iast": ["tad viddhi praṇipātena paripraśnena sevayā", "upadekṣyanti te jñānaṃ jñāninas tattva-darśinaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Apréndelo postrándote ante ellos, preguntándoles y sirviéndoles: los sabios que ven la realidad te enseñarán el <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a>.</span>", "palabras": [{"iast": "tat", "sa": "तत्", "gram": "ac. sg. n. pron.", "es": "eso (el conocimiento)"}, {"iast": "viddhi", "sa": "विद्धि", "gram": "2 sg. impv. act.", "es": "aprende, conoce", "analisis": "√vid (saber)"}, {"iast": "praṇipātena", "sa": "प्रणिपातेन", "gram": "instr. sg. m.", "es": "con la postración, con reverencia", "analisis": "pra-ni-√pat (caer, postrarse)"}, {"iast": "paripraśnena", "sa": "परिप्रश्नेन", "gram": "instr. sg. m.", "es": "preguntando, con preguntas", "analisis": "pari (en torno, a fondo) + praśna (pregunta; de √prach, preguntar)"}, {"iast": "sevayā", "sa": "सेवया", "gram": "instr. sg. f.", "es": "con el servicio", "analisis": "√sev (servir, atender)"}, {"iast": "upadekṣyanti", "sa": "उपदेक्ष्यन्ति", "gram": "3 pl. fut. act.", "es": "enseñarán", "analisis": "upa-√diś (mostrar, enseñar)"}, {"iast": "te", "sa": "ते", "gram": "dat. sg. pron.", "es": "a ti"}, {"iast": "jñānam", "sa": "ज्ञानम्", "gram": "ac. sg. n.", "es": "el conocimiento", "ref": "jnana"}, {"iast": "jñāninaḥ", "sa": "ज्ञानिनः", "gram": "nom. pl. m.", "es": "los sabios, los que conocen", "analisis": "jñānin (el que posee conocimiento)"}, {"iast": "tattva-darśinaḥ", "sa": "तत्त्वदर्शिनः", "gram": "nom. pl. m. comp.", "es": "que ven la realidad", "analisis": "tattva (la realidad, lo que una cosa es; de tad, «eso», + -tva) + darśin (que ve; de √dṛś)"}], "nota": "<p>«Eso» es el conocimiento del que acaba de hablar el verso anterior, el sacrificio del conocimiento, en el que culmina toda acción (<a class=\"vref\" href=\"capitulo-04.html#v33\" data-v=\"4.33\">4.33</a>). El verso describe cómo se recibe: no por la sola lectura, sino de un maestro, y con tres disposiciones del discípulo —la reverencia, la pregunta y el servicio—.</p><p>Los maestros reciben dos calificativos: <em>jñānin</em>, «que conoce», y <em>tattva-darśin</em>, «que ve la realidad». Es la misma expresión de <a class=\"vref\" href=\"capitulo-02.html#v16\" data-v=\"2.16\">2.16</a>, «los que ven la realidad». El segundo precisa el primero: no basta con saber la doctrina, hay que haberla visto.</p>", "interp": [{"titulo": "El discípulo ante el maestro", "html": "<p>El verso resume la relación entre maestro y discípulo que describen las <a class=\"t\" href=\"glosario.html#upanisad\" data-t=\"upanisad\">Upaniṣads</a>. La <a class=\"t\" href=\"glosario.html#upanisad\" data-t=\"upanisad\">Muṇḍaka Upaniṣad</a> (1.2.12) pide al que busca conocer brahman que vaya «con leña en la mano» —la ofrenda del aspirante— a un maestro versado en el Veda y establecido en brahman. La Gītā, que en el resto de la enseñanza habla de Kṛṣṇa como único maestro, reconoce aquí la cadena humana de transmisión de la que hablaba al comienzo del capítulo (<a class=\"vref\" href=\"capitulo-04.html#v1\" data-v=\"4.1\">4.1</a>–<a class=\"vref\" href=\"capitulo-04.html#v3\" data-v=\"4.3\">4.3</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "Saber y ver", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> se detiene en el doble calificativo de los maestros: hay quienes tienen conocimiento sin haber visto la realidad tal como es, y por eso el verso precisa «los que ven la realidad». Sólo el conocimiento enseñado por ellos produce su efecto.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Preguntar no es dudar", "html": "<p>Muchos lectores modernos subrayan que el verso pone la pregunta entre las virtudes del discípulo, junto a la reverencia y el servicio. La enseñanza no se recibe en silencio: se interroga. Pero la pregunta que pide el texto es la de quien busca entender, no la del que objeta para no comprometerse; la diferencia reaparece al final del capítulo, donde la duda que paraliza es lo que hay que cortar (<a class=\"vref\" href=\"capitulo-04.html#v40\" data-v=\"4.40\">4.40</a>–<a class=\"vref\" href=\"capitulo-04.html#v42\" data-v=\"4.42\">4.42</a>).</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Apréndelo con humildad, con preguntas sinceras y con servicio: los sabios que ven la realidad te enseñarán el <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a>.", "nota": "<p><em>Praṇipāta</em> es literalmente «postración», el gesto de echarse a los pies del maestro; muchas traducciones lo vierten por la actitud que expresa, «humildad, reverencia». <em>Paripraśna</em> no es una pregunta cualquiera: el prefijo <em>pari</em>, «en torno», sugiere la pregunta que se vuelve una y otra vez sobre el asunto hasta agotarlo. La traducción principal conserva los gestos concretos de la relación tradicional con el maestro; esta alternativa, las disposiciones interiores que esos gestos significan.</p>"}], "ens": "recibir-el-conocimiento"}, {"n": 35, "hablante": "krsna", "sa": ["यज्ज्ञात्वा न पुनर्मोहमेवं यास्यसि पाण्डव ।", "येन भूतान्यशेषेण द्रक्ष्यस्यात्मन्यथो मयि ॥३५॥"], "iast": ["yaj jñātvā na punar moham evaṃ yāsyasi pāṇḍava", "yena bhūtāny aśeṣeṇa drakṣyasy ātmany atho mayi"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Cuando lo conozcas, oh <a class=\"t\" href=\"glosario.html#pandava\" data-t=\"pandava\">Pāṇḍava</a>, ya no volverás a caer así en el <a class=\"t\" href=\"glosario.html#moha\" data-t=\"moha\">extravío</a>: por él verás a todos los seres, sin excepción, en el <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">sí-mismo</a>, y también en mí.</span>", "palabras": [{"iast": "yat", "sa": "यत्", "gram": "ac. sg. n. pron.", "es": "lo cual (ese conocimiento)"}, {"iast": "jñātvā", "sa": "ज्ञात्वा", "gram": "abs.", "es": "conociendo, una vez conocido", "analisis": "√jñā (conocer)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "punar", "sa": "पुनर्", "gram": "ind.", "es": "de nuevo"}, {"iast": "moham", "sa": "मोहम्", "gram": "ac. sg. m.", "es": "el extravío", "ref": "moha"}, {"iast": "evam", "sa": "एवम्", "gram": "ind.", "es": "así, de este modo"}, {"iast": "yāsyasi", "sa": "यास्यसि", "gram": "2 sg. fut. act.", "es": "irás, caerás", "analisis": "√yā (ir)"}, {"iast": "pāṇḍava", "sa": "पाण्डव", "gram": "voc. sg. m.", "es": "oh Pāṇḍava, hijo de Pāṇḍu", "ref": "pandava"}, {"iast": "yena", "sa": "येन", "gram": "instr. sg. n. pron.", "es": "por el cual"}, {"iast": "bhūtāni", "sa": "भूतानि", "gram": "ac. pl. n.", "es": "los seres", "analisis": "√bhū (llegar a ser)"}, {"iast": "aśeṣeṇa", "sa": "अशेषेण", "gram": "instr. sg. m.", "es": "sin excepción, por entero", "analisis": "a (sin) + śeṣa (resto)"}, {"iast": "drakṣyasi", "sa": "द्रक्ष्यसि", "gram": "2 sg. fut. act.", "es": "verás", "analisis": "√dṛś (ver)"}, {"iast": "ātmani", "sa": "आत्मनि", "gram": "loc. sg. m.", "es": "en el sí-mismo", "ref": "atman"}, {"iast": "atho", "sa": "अथो", "gram": "ind.", "es": "y luego, y también"}, {"iast": "mayi", "sa": "मयि", "gram": "loc. sg. pron.", "es": "en mí"}], "nota": "<p>«Así» remite al extravío que ha paralizado a Arjuna desde <a class=\"vref\" href=\"capitulo-01.html#v28\" data-v=\"1.28\">1.28</a> y que él mismo reconocía en <a class=\"vref\" href=\"capitulo-02.html#v7\" data-v=\"2.7\">2.7</a>: ver a los suyos sólo como parientes que hay que llorar. El conocimiento no suprime la percepción de los seres, sino que la sitúa: todos están en el sí-mismo y, a la vez, en Kṛṣṇa.</p><p>La misma visión volverá en <a class=\"vref\" href=\"capitulo-06.html#v29\" data-v=\"6.29\">6.29</a>–<a class=\"vref\" href=\"capitulo-06.html#v30\" data-v=\"6.30\">6.30</a>: el yogui «ve el sí-mismo en todos los seres y a todos los seres en el sí-mismo», y «a mí en todas partes y todo en mí». Cómo se relacionan esos dos términos —el sí-mismo y Kṛṣṇa— es justamente lo que separa a las escuelas.</p>", "interp": [{"titulo": "Uno solo", "html": "<p>Para la lectura del <a class=\"t\" href=\"glosario.html#advaita\" data-t=\"advaita\">Advaita</a>, ver a los seres «en el sí-mismo y también en mí» es descubrir que el sí-mismo de cada uno y el Señor son una sola realidad: el conocedor ve que no hay nada fuera de ella. La conjunción <em>atho</em>, «y también», no añade un segundo lugar, sino que nombra el mismo desde otro lado.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Semejantes, no idénticos", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lee la frase de otro modo: libres de la naturaleza material, todos los sí-mismos tienen la misma forma esencial, la del conocimiento, y por eso el que conoce ve a los seres «en el sí-mismo», iguales al suyo; y los ve «en mí» porque esa forma esencial se asemeja a la del Señor. Es una igualdad de naturaleza (<em>sāmya</em>), no una identidad.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-conocimiento-que-purifica"}, {"n": 36, "hablante": "krsna", "sa": ["अपि चेदसि पापेभ्यः सर्वेभ्यः पापकृत्तमः ।", "सर्वं ज्ञानप्लवेनैव वृजिनं सन्तरिष्यसि ॥३६॥"], "iast": ["api ced asi pāpebhyaḥ sarvebhyaḥ pāpa-kṛt-tamaḥ", "sarvaṃ jñāna-plavenaiva vṛjinaṃ santariṣyasi"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Aunque fueras el mayor pecador entre todos los pecadores, con la sola barca del <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a> atravesarías todo el mal.</span>", "palabras": [{"iast": "api", "sa": "अपि", "gram": "ind.", "es": "aun"}, {"iast": "ced", "sa": "चेद्", "gram": "ind.", "es": "si"}, {"iast": "asi", "sa": "असि", "gram": "2 sg. pres. act.", "es": "eres", "analisis": "√as (ser)"}, {"iast": "pāpebhyaḥ", "sa": "पापेभ्यः", "gram": "abl. pl. m.", "es": "que los pecadores", "ref": "papa"}, {"iast": "sarvebhyaḥ", "sa": "सर्वेभ्यः", "gram": "abl. pl. m. pron.", "es": "que todos"}, {"iast": "pāpa-kṛt-tamaḥ", "sa": "पापकृत्तमः", "gram": "nom. sg. m. comp.", "es": "el mayor pecador", "analisis": "pāpa (pecado) + kṛt (que hace; de √kṛ) + -tama (sufijo de superlativo)"}, {"iast": "sarvam", "sa": "सर्वम्", "gram": "ac. sg. n. pron.", "es": "todo"}, {"iast": "jñāna-plavena", "sa": "ज्ञानप्लवेन", "gram": "instr. sg. m. comp.", "es": "con la barca del conocimiento", "ref": "jnana", "analisis": "jñāna (conocimiento) + plava (balsa, barca; de √plu, flotar)"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "sólo, precisamente"}, {"iast": "vṛjinam", "sa": "वृजिनम्", "gram": "ac. sg. n.", "es": "el mal", "analisis": "vṛjina (literalmente «torcido»; de ahí «mal, maldad»)"}, {"iast": "santariṣyasi", "sa": "सन्तरिष्यसि", "gram": "2 sg. fut. act.", "es": "cruzarás", "analisis": "sam-√tṝ (atravesar, cruzar a la otra orilla)"}], "nota": "<p>La imagen del saṃsāra como un río o un océano que hay que cruzar es antigua y común a las tradiciones de la India: el que se libera «pasa a la otra orilla». El conocimiento es aquí la barca; en el verso siguiente será el fuego.</p><p>El verso no rebaja la gravedad del mal, sino que afirma que no hay pasado que impida el conocimiento. Kṛṣṇa dirá algo semejante de la devoción en <a class=\"vref\" href=\"capitulo-09.html#v30\" data-v=\"9.30\">9.30</a>: aun el de peor conducta, si lo adora con entrega exclusiva, ha de ser tenido por bueno.</p>", "interp": [{"titulo": "También el mérito ata", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> observa que para quien busca la liberación el «mal» del que habla el verso incluye también el mérito (<em>dharma</em>): las buenas acciones atan igual que las malas, porque también ellas producen frutos que hay que vivir en nuevos nacimientos. El conocimiento libera de ambas cosas.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "La barca y la otra orilla", "html": "<p>La imagen del verso recorre la literatura religiosa de la India. Las <a class=\"t\" href=\"glosario.html#upanisad\" data-t=\"upanisad\">Upaniṣads</a> hablan del brahman como la otra orilla, y el budismo llamará a su doctrina una balsa que sirve para cruzar el río y que no hay que cargar una vez cruzado. En la Gītā el conocimiento es la barca, pero en <a class=\"vref\" href=\"capitulo-12.html#v7\" data-v=\"12.7\">12.7</a> Kṛṣṇa dirá que él mismo es quien saca a sus devotos «del océano de la muerte y del saṃsāra».</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-conocimiento-que-purifica"}, {"n": 37, "hablante": "krsna", "sa": ["यथैधांसि समिद्धोऽग्निर्भस्मसात्कुरुतेऽर्जुन ।", "ज्ञानाग्निः सर्वकर्माणि भस्मसात्कुरुते तथा ॥३७॥"], "iast": ["yathaidhāṃsi samiddho 'gnir bhasmasāt kurute 'rjuna", "jñānāgniḥ sarva-karmāṇi bhasmasāt kurute tathā"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Así como el fuego encendido reduce a cenizas la leña, oh <a class=\"t\" href=\"glosario.html#arjuna\" data-t=\"arjuna\">Arjuna</a>, así el fuego del <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a> reduce a cenizas todas las <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acciones</a>.</span>", "palabras": [{"iast": "yathā", "sa": "यथा", "gram": "ind.", "es": "así como"}, {"iast": "edhāṃsi", "sa": "एधांसि", "gram": "ac. pl. n.", "es": "la leña", "analisis": "edhas (leña, combustible; de √idh, encender)"}, {"iast": "samiddhaḥ", "sa": "समिद्धः", "gram": "nom. sg. m. ppp", "es": "encendido, avivado", "analisis": "sam-√idh (encender)"}, {"iast": "agniḥ", "sa": "अग्निः", "gram": "nom. sg. m.", "es": "el fuego"}, {"iast": "bhasmasāt", "sa": "भस्मसात्", "gram": "ind.", "es": "en cenizas", "analisis": "bhasman (ceniza) + -sāt (sufijo que indica conversión completa en algo)"}, {"iast": "kurute", "sa": "कुरुते", "gram": "3 sg. pres. med.", "es": "convierte, reduce", "analisis": "√kṛ (hacer)"}, {"iast": "arjuna", "sa": "अर्जुन", "gram": "voc. sg. m.", "es": "oh Arjuna", "ref": "arjuna"}, {"iast": "jñāna-agniḥ", "sa": "ज्ञानाग्निः", "gram": "nom. sg. m. comp.", "es": "el fuego del conocimiento", "ref": "jnana", "analisis": "jñāna (conocimiento) + agni (fuego)"}, {"iast": "sarva-karmāṇi", "sa": "सर्वकर्माणि", "gram": "ac. pl. n. comp.", "es": "todas las acciones", "ref": "karma"}, {"iast": "bhasmasāt", "sa": "भस्मसात्", "gram": "ind.", "es": "en cenizas"}, {"iast": "kurute", "sa": "कुरुते", "gram": "3 sg. pres. med.", "es": "reduce"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "así"}], "nota": "<p>Las «acciones» son aquí sus huellas y sus frutos pendientes: lo que, según la ley de la retribución, ataría al que actuó a nuevas experiencias y nacimientos. El fuego del conocimiento las consume, como antes se dijo del sabio cuyas acciones «quema el fuego del conocimiento» (<a class=\"vref\" href=\"capitulo-04.html#v19\" data-v=\"4.19\">4.19</a>).</p><p>La imagen es ritual: el fuego del sacrificio convierte en ceniza lo que se le ofrece. Tras la larga enumeración de sacrificios de <a class=\"vref\" href=\"capitulo-04.html#v25\" data-v=\"4.25\">4.25</a>–<a class=\"vref\" href=\"capitulo-04.html#v30\" data-v=\"4.30\">4.30</a>, el conocimiento aparece como el fuego en el que se ofrece la acción misma.</p>", "interp": [{"titulo": "Lo que el fuego no quema", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> precisa el alcance de «todas las acciones»: el conocimiento consume las acciones acumuladas que todavía no han dado fruto y las que se hagan después, pero no las que ya han empezado a darlo, porque de ellas nació el cuerpo presente. Ésas se agotan viviéndolas. Por eso el sabio liberado en vida sigue teniendo un cuerpo hasta que se acaba el impulso que lo produjo.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-conocimiento-que-purifica"}, {"n": 38, "hablante": "krsna", "sa": ["न हि ज्ञानेन सदृशं पवित्रमिह विद्यते ।", "तत्स्वयं योगसंसिद्धः कालेनात्मनि विन्दति ॥३८॥"], "iast": ["na hi jñānena sadṛśaṃ pavitram iha vidyate", "tat svayaṃ yoga-saṃsiddhaḥ kālenātmani vindati"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Nada hay en este mundo que purifique como el <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a>. Quien ha llegado a la perfección por el <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a> lo encuentra a su tiempo, por sí mismo, dentro de sí.</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues, en verdad"}, {"iast": "jñānena", "sa": "ज्ञानेन", "gram": "instr. sg. n.", "es": "al conocimiento (semejante a)", "ref": "jnana"}, {"iast": "sadṛśam", "sa": "सदृशम्", "gram": "nom. sg. n. adj.", "es": "semejante, comparable", "analisis": "sa (con) + dṛś (aspecto)"}, {"iast": "pavitram", "sa": "पवित्रम्", "gram": "nom. sg. n.", "es": "purificador, lo que purifica", "analisis": "√pū (purificar)"}, {"iast": "iha", "sa": "इह", "gram": "ind.", "es": "aquí, en este mundo"}, {"iast": "vidyate", "sa": "विद्यते", "gram": "3 sg. pres. pas.", "es": "hay, se encuentra", "analisis": "√vid (hallarse, existir)"}, {"iast": "tat", "sa": "तत्", "gram": "ac. sg. n. pron.", "es": "eso (el conocimiento)"}, {"iast": "svayam", "sa": "स्वयम्", "gram": "ind.", "es": "por sí mismo"}, {"iast": "yoga-saṃsiddhaḥ", "sa": "योगसंसिद्धः", "gram": "nom. sg. m. comp.", "es": "el que ha llegado a la perfección por el yoga", "ref": "yoga", "analisis": "yoga + saṃsiddha (perfeccionado, logrado; de sam-√sidh, cumplirse)"}, {"iast": "kālena", "sa": "कालेन", "gram": "instr. sg. m.", "es": "con el tiempo, a su tiempo"}, {"iast": "ātmani", "sa": "आत्मनि", "gram": "loc. sg. m.", "es": "en sí mismo", "ref": "atman"}, {"iast": "vindati", "sa": "विन्दति", "gram": "3 sg. pres. act.", "es": "encuentra, halla", "analisis": "√vid (hallar)"}], "nota": "<p><em>Pavitra</em> es lo que purifica en sentido ritual: el agua, el fuego, los cánticos que limpian de impureza. Kṛṣṇa traslada la palabra al conocimiento, como antes trasladó la del sacrificio (<a class=\"vref\" href=\"capitulo-04.html#v33\" data-v=\"4.33\">4.33</a>).</p><p>La segunda mitad matiza la primera. El conocimiento se recibe de los maestros (<a class=\"vref\" href=\"capitulo-04.html#v34\" data-v=\"4.34\">4.34</a>), pero no se adquiere como una noticia: hay que haberse preparado por el yoga, y llega «a su tiempo» y «por sí mismo», como algo que se descubre dentro y no como algo que se transmite de fuera.</p>", "interp": [{"titulo": "Un largo camino", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende al «perfeccionado por el yoga» como el que se ha preparado con el <a class=\"t\" href=\"glosario.html#karma-yoga\" data-t=\"karma-yoga\">yoga de la acción</a> y con la concentración, y lee <em>kālena</em> como «tras largo tiempo»: el conocimiento es inmediato cuando llega, pero el camino hasta él es largo.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Recibido y descubierto", "html": "<p>Los versos <a class=\"vref\" href=\"capitulo-04.html#v34\" data-v=\"4.34\">4.34</a> y 4.38 forman una pareja. En el primero el conocimiento viene de fuera, de los maestros que ven la realidad; en el segundo se encuentra dentro, por uno mismo. La Gītā no opone las dos cosas: la enseñanza del maestro prepara lo que sólo la propia experiencia confirma.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Nada hay en este mundo que purifique como el <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a>. Con el tiempo, el que ha llegado a la perfección por el <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a> lo halla él mismo en el <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">sí-mismo</a>.", "nota": "<p><em>Ātmani</em> es el locativo de <em>ātman</em>, que puede ser un simple reflexivo, «en sí mismo, dentro de sí», o el concepto filosófico, «en el sí-mismo». La traducción principal elige el reflexivo: el conocimiento no se recibe de fuera, sino que madura en el propio interior. La alternativa da a <em>ātman</em> su sentido pleno: lo que se encuentra es el conocimiento que tiene por objeto y por lugar el sí-mismo. <em>Kālena</em>, «con el tiempo», admite también los dos matices: «a su debido tiempo» o «tras mucho tiempo».</p>"}], "ens": "el-conocimiento-que-purifica"}, {"n": 39, "hablante": "krsna", "sa": ["श्रद्धावाँल्लभते ज्ञानं तत्परः संयतेन्द्रियः ।", "ज्ञानं लब्ध्वा परां शान्तिमचिरेणाधिगच्छति ॥३९॥"], "iast": ["śraddhāvāṁl labhate jñānaṃ tat-paraḥ saṃyatendriyaḥ", "jñānaṃ labdhvā parāṃ śāntim acireṇādhigacchati"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">El que tiene <a class=\"t\" href=\"glosario.html#sraddha\" data-t=\"sraddha\">fe</a>, entregado a él y con los <a class=\"t\" href=\"glosario.html#indriya\" data-t=\"indriya\">sentidos</a> dominados, alcanza el <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a>; y, alcanzado el conocimiento, llega sin tardanza a la <a class=\"t\" href=\"glosario.html#santi\" data-t=\"santi\">paz</a> suprema.</span>", "palabras": [{"iast": "śraddhāvān", "sa": "श्रद्धावान्", "gram": "nom. sg. m. adj.", "es": "el que tiene fe", "ref": "sraddha", "analisis": "śraddhā (fe) + -vat (que posee)"}, {"iast": "labhate", "sa": "लभते", "gram": "3 sg. pres. med.", "es": "alcanza, obtiene", "analisis": "√labh (tomar, obtener)"}, {"iast": "jñānam", "sa": "ज्ञानम्", "gram": "ac. sg. n.", "es": "el conocimiento", "ref": "jnana"}, {"iast": "tat-paraḥ", "sa": "तत्परः", "gram": "nom. sg. m. comp.", "es": "entregado a ello, que lo tiene por meta", "analisis": "tat (eso) + para (supremo, meta)"}, {"iast": "saṃyata-indriyaḥ", "sa": "संयतेन्द्रियः", "gram": "nom. sg. m. comp.", "es": "con los sentidos dominados", "ref": "indriya", "analisis": "saṃyata (dominado, refrenado; de sam-√yam) + indriya (sentido)"}, {"iast": "jñānam", "sa": "ज्ञानम्", "gram": "ac. sg. n.", "es": "el conocimiento"}, {"iast": "labdhvā", "sa": "लब्ध्वा", "gram": "abs.", "es": "una vez alcanzado", "analisis": "√labh"}, {"iast": "parām", "sa": "पराम्", "gram": "ac. sg. f. adj.", "es": "suprema"}, {"iast": "śāntim", "sa": "शान्तिम्", "gram": "ac. sg. f.", "es": "la paz", "ref": "santi"}, {"iast": "acireṇa", "sa": "अचिरेण", "gram": "instr. sg. n. adv.", "es": "sin tardanza, pronto", "analisis": "a (no) + cira (largo tiempo)"}, {"iast": "adhigacchati", "sa": "अधिगच्छति", "gram": "3 sg. pres. act.", "es": "llega a, alcanza", "analisis": "adhi-√gam (llegar a)"}], "nota": "<p>Tres condiciones para el conocimiento: la fe, la entrega a él como meta (<em>tat-para</em>) y el dominio de los sentidos. Las dos primeras miran a la enseñanza; la tercera, a la disciplina de <a class=\"vref\" href=\"capitulo-02.html#v58\" data-v=\"2.58\">2.58</a>–<a class=\"vref\" href=\"capitulo-02.html#v61\" data-v=\"2.61\">2.61</a> y <a class=\"vref\" href=\"capitulo-03.html#v41\" data-v=\"3.41\">3.41</a>.</p><p>La fe es aquí la confianza que pone en marcha la búsqueda: la de quien da crédito a la enseñanza y al maestro lo bastante para emprender el camino. La paz suprema que sigue al conocimiento es la del de sabiduría firme del final del capítulo 2 (<a class=\"vref\" href=\"capitulo-02.html#v70\" data-v=\"2.70\">2.70</a>–<a class=\"vref\" href=\"capitulo-02.html#v71\" data-v=\"2.71\">2.71</a>).</p>", "interp": [{"titulo": "La fe como comienzo", "html": "<p>En la Gītā la <a class=\"t\" href=\"glosario.html#sraddha\" data-t=\"sraddha\">fe</a> no es la adhesión a un dogma, sino la confianza que dispone a buscar. Por eso puede ponerse al principio del camino del conocimiento: el que no da crédito a la enseñanza no la practica, y sin práctica no llega a comprobarla. El capítulo 17 hará de la fe la medida de la persona: «el hombre está hecho de fe; lo que es su fe, eso es él» (<a class=\"vref\" href=\"capitulo-17.html#v3\" data-v=\"17.3\">17.3</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "Entregado a él", "html": "<p>Las lecturas devocionales hacen notar el <em>tat-para</em> del verso, «entregado a ello», que repite el <em>mat-para</em>, «entregado a mí», de <a class=\"vref\" href=\"capitulo-02.html#v61\" data-v=\"2.61\">2.61</a>. Para ellas la fe que lleva al conocimiento es ya una forma de devoción: confiar en la palabra de Kṛṣṇa y hacer de ella la meta.</p>", "trad": "devocional", "tradNombre": "Lecturas devocionales"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "la-fe-y-la-duda"}, {"n": 40, "hablante": "krsna", "sa": ["अज्ञश्चाश्रद्दधानश्च संशयात्मा विनश्यति ।", "नायं लोकोऽस्ति न परो न सुखं संशयात्मनः ॥४०॥"], "iast": ["ajñaś cāśraddadhānaś ca saṃśayātmā vinaśyati", "nāyaṃ loko 'sti na paro na sukhaṃ saṃśayātmanaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Pero el ignorante, el que no tiene fe y vive en la <a class=\"t\" href=\"glosario.html#samsaya\" data-t=\"samsaya\">duda</a>, se pierde: para el que duda no hay este mundo, ni el otro, ni felicidad.</span>", "palabras": [{"iast": "ajñaḥ", "sa": "अज्ञः", "gram": "nom. sg. m.", "es": "el ignorante", "analisis": "a (no) + jña (que conoce)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "aśraddadhānaḥ", "sa": "अश्रद्दधानः", "gram": "nom. sg. m. part.", "es": "el que no tiene fe", "analisis": "a (no) + śraddadhāna (part. pres. med. de śrad-√dhā, «tener fe»)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "saṃśaya-ātmā", "sa": "संशयात्मा", "gram": "nom. sg. m. comp.", "es": "el que vive en la duda, aquel cuya mente es duda", "ref": "samsaya", "analisis": "saṃśaya (duda) + ātman (sí mismo, mente)"}, {"iast": "vinaśyati", "sa": "विनश्यति", "gram": "3 sg. pres. act.", "es": "se pierde, perece", "analisis": "vi-√naś (perecer)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "ayam", "sa": "अयम्", "gram": "nom. sg. m. pron.", "es": "este"}, {"iast": "lokaḥ", "sa": "लोकः", "gram": "nom. sg. m.", "es": "mundo"}, {"iast": "asti", "sa": "अस्ति", "gram": "3 sg. pres. act.", "es": "hay", "analisis": "√as (ser)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "ni"}, {"iast": "paraḥ", "sa": "परः", "gram": "nom. sg. m. adj.", "es": "el otro, el de más allá"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "ni"}, {"iast": "sukham", "sa": "सुखम्", "gram": "nom. sg. n.", "es": "felicidad"}, {"iast": "saṃśaya-ātmanaḥ", "sa": "संशयात्मनः", "gram": "gen. sg. m. comp.", "es": "para el que vive en la duda", "ref": "samsaya"}], "nota": "<p>El verso es el reverso del anterior: frente al que tiene fe, entregado y dominado, el ignorante, el que no tiene fe y el que duda. El tercero es el que más pierde: no tiene «este mundo», porque no se compromete en nada, ni «el otro», porque no emprende el camino que lleva a él.</p><p>La duda de la que habla Kṛṣṇa no es la pregunta del discípulo que busca entender (<a class=\"vref\" href=\"capitulo-04.html#v34\" data-v=\"4.34\">4.34</a>), sino la indecisión que impide actuar y conocer: la del entendimiento «de muchas ramas» de los irresolutos (<a class=\"vref\" href=\"capitulo-02.html#v41\" data-v=\"2.41\">2.41</a>).</p>", "interp": [{"titulo": "El peor de los tres", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> compara a los tres personajes del verso: el ignorante y el que no tiene fe se pierden, pero el que duda es el peor de todos, porque ni siquiera disfruta de este mundo: la duda no lo deja descansar en nada.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Duda y crítica", "html": "<p>La valoración negativa de la duda choca con la sensibilidad moderna, que ve en ella el motor del pensamiento crítico. Muchos lectores la matizan: el verso no condena el examen, que la Gītā misma pide al discípulo, sino la duda crónica que impide decidir. La tradición filosófica india conoce bien el valor de la duda como punto de partida: el Nyāya, la escuela de la lógica, la cuenta entre los elementos de toda indagación. Lo que se reprocha aquí es quedarse en ella.</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Pero el ignorante, el que no tiene fe, aquel cuya mente es duda, se pierde: para él no hay este mundo, ni el otro, ni felicidad.", "nota": "<p><em>Saṃśayātman</em> es un compuesto que puede leerse «el que tiene la mente (<em>ātman</em>) en la duda» o, más fuerte, «aquel cuyo ser es duda». No se trata de quien duda de algo en un momento dado, sino de quien ha hecho de la duda su manera de estar: nunca se decide. La traducción principal lo vierte por «el que vive en la duda»; la alternativa conserva la imagen del compuesto.</p>"}], "ens": "la-fe-y-la-duda"}, {"n": 41, "hablante": "krsna", "sa": ["योगसंन्यस्तकर्माणं ज्ञानसञ्छिन्नसंशयम् ।", "आत्मवन्तं न कर्माणि निबध्नन्ति धनञ्जय ॥४१॥"], "iast": ["yoga-saṃnyasta-karmāṇaṃ jñāna-sañchinna-saṃśayam", "ātmavantaṃ na karmāṇi nibadhnanti dhanañjaya"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Al que ha renunciado a las acciones por el <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a>, al que ha cortado la duda con el <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a>, al dueño de sí, no lo atan las <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acciones</a>, oh <a class=\"t\" href=\"glosario.html#dhananjaya\" data-t=\"dhananjaya\">Dhanañjaya</a>.</span>", "palabras": [{"iast": "yoga-saṃnyasta-karmāṇam", "sa": "योगसंन्यस्तकर्माणम्", "gram": "ac. sg. m. comp.", "es": "al que ha renunciado a las acciones por el yoga", "ref": "sannyasa", "analisis": "yoga + saṃnyasta (depositado, renunciado; de sam-ni-√as, arrojar) + karman (acción)"}, {"iast": "jñāna-sañchinna-saṃśayam", "sa": "ज्ञानसञ्छिन्नसंशयम्", "gram": "ac. sg. m. comp.", "es": "que ha cortado la duda con el conocimiento", "ref": "samsaya", "analisis": "jñāna (conocimiento) + sañchinna (cortado del todo; de sam-√chid) + saṃśaya (duda)"}, {"iast": "ātmavantam", "sa": "आत्मवन्तम्", "gram": "ac. sg. m. adj.", "es": "al dueño de sí", "analisis": "ātman (sí mismo) + -vat (que posee)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "karmāṇi", "sa": "कर्माणि", "gram": "nom. pl. n.", "es": "las acciones", "ref": "karma"}, {"iast": "nibadhnanti", "sa": "निबध्नन्ति", "gram": "3 pl. pres. act.", "es": "atan", "analisis": "ni-√bandh (atar)"}, {"iast": "dhanañjaya", "sa": "धनञ्जय", "gram": "voc. sg. m.", "es": "oh Dhanañjaya, conquistador de riquezas", "ref": "dhananjaya"}], "nota": "<p>El verso reúne las dos vías del capítulo, como lo anuncia su título: la renuncia (<em>saṃnyāsa</em>) a las acciones y el conocimiento que corta la duda. Una tercera cualidad, <em>ātmavat</em>, «el que se posee a sí mismo», recoge la disciplina de los sentidos de los versos anteriores.</p><p>Es la respuesta a la pregunta con que empezó la exposición sobre la acción (<a class=\"vref\" href=\"capitulo-04.html#v16\" data-v=\"4.16\">4.16</a>–<a class=\"vref\" href=\"capitulo-04.html#v18\" data-v=\"4.18\">4.18</a>): lo que hace que la acción ate no es la acción misma, sino el modo de hacerla.</p>", "interp": [{"titulo": "La renuncia por el conocimiento", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende aquí <em>yoga</em> como la visión de la realidad suprema: el que ha visto que el sí-mismo no actúa ha renunciado de raíz a toda acción, porque ya no se tiene por su autor. Para él el verso describe al sabio renunciante.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Las acciones puestas en manos del Señor", "html": "<p>Las lecturas que dan prioridad a la acción y a la devoción leen la «renuncia por el yoga» a la luz de <a class=\"vref\" href=\"capitulo-03.html#v30\" data-v=\"3.30\">3.30</a>: no es dejar de actuar, sino depositar las acciones en el Señor y obrar sin pretender sus frutos. El mismo verbo sirve para las dos cosas, y el verso puede leerse en los dos sentidos.</p>", "trad": "devocional", "tradNombre": "Lecturas devocionales"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Al que ha depositado sus acciones mediante el <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a>, al que ha cortado la duda con el <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a>, al dueño de sí, no lo atan las <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acciones</a>, oh <a class=\"t\" href=\"glosario.html#dhananjaya\" data-t=\"dhananjaya\">Dhanañjaya</a>.", "nota": "<p><em>Saṃnyasta</em> es el participio del mismo verbo que da <em>saṃnyāsa</em>, «renuncia», pero su sentido literal es «puesto, depositado del todo». En <a class=\"vref\" href=\"capitulo-03.html#v30\" data-v=\"3.30\">3.30</a> Kṛṣṇa pedía «depositar en mí» todas las acciones con ese verbo. Según qué se entienda por <em>yoga</em> —el conocimiento de la realidad suprema o el yoga de la acción ofrecida—, el que «ha renunciado a las acciones por el yoga» es el renunciante que ya no actúa o el que sigue actuando pero ha dejado las acciones en manos del Señor.</p>"}], "ens": "cortar-la-duda"}, {"n": 42, "hablante": "krsna", "sa": ["तस्मादज्ञानसम्भूतं हृत्स्थं ज्ञानासिनात्मनः ।", "छित्त्वैनं संशयं योगमातिष्ठोत्तिष्ठ भारत ॥४२॥"], "iast": ["tasmād ajñāna-sambhūtaṃ hṛt-sthaṃ jñānāsinātmanaḥ", "chittvainaṃ saṃśayaṃ yogam ātiṣṭhottiṣṭha bhārata"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Por eso, corta con la espada del <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a> esta <a class=\"t\" href=\"glosario.html#samsaya\" data-t=\"samsaya\">duda</a> tuya, nacida de la ignorancia, que está en tu corazón; aférrate al <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a> y levántate, oh <a class=\"t\" href=\"glosario.html#bharata\" data-t=\"bharata\">Bhārata</a>.</span>", "palabras": [{"iast": "tasmāt", "sa": "तस्मात्", "gram": "abl. sg. n. pron.", "es": "por eso"}, {"iast": "ajñāna-sambhūtam", "sa": "अज्ञानसम्भूतम्", "gram": "ac. sg. m. comp.", "es": "nacido de la ignorancia", "analisis": "ajñāna (ignorancia; a + jñāna) + sambhūta (nacido; de sam-√bhū)"}, {"iast": "hṛt-stham", "sa": "हृत्स्थम्", "gram": "ac. sg. m. comp.", "es": "que está en el corazón", "analisis": "hṛd (corazón) + stha (que está; de √sthā)"}, {"iast": "jñāna-asinā", "sa": "ज्ञानासिना", "gram": "instr. sg. m. comp.", "es": "con la espada del conocimiento", "ref": "jnana", "analisis": "jñāna (conocimiento) + asi (espada)"}, {"iast": "ātmanaḥ", "sa": "आत्मनः", "gram": "gen. sg. m.", "es": "tuyo, de ti mismo", "analisis": "ātman, aquí como reflexivo"}, {"iast": "chittvā", "sa": "छित्त्वा", "gram": "abs.", "es": "cortando, tras cortar", "analisis": "√chid (cortar)"}, {"iast": "enam", "sa": "एनम्", "gram": "ac. sg. m. pron.", "es": "esta"}, {"iast": "saṃśayam", "sa": "संशयम्", "gram": "ac. sg. m.", "es": "la duda", "ref": "samsaya"}, {"iast": "yogam", "sa": "योगम्", "gram": "ac. sg. m.", "es": "al yoga", "ref": "yoga"}, {"iast": "ātiṣṭha", "sa": "आतिष्ठ", "gram": "2 sg. impv. act.", "es": "aférrate a, recurre a", "analisis": "ā-√sthā (estar en, recurrir a)"}, {"iast": "uttiṣṭha", "sa": "उत्तिष्ठ", "gram": "2 sg. impv. act.", "es": "levántate", "analisis": "ud-√sthā (ponerse en pie)"}, {"iast": "bhārata", "sa": "भारत", "gram": "voc. sg. m.", "es": "oh Bhārata", "ref": "bharata"}], "nota": "<p>El capítulo termina como el anterior (<a class=\"vref\" href=\"capitulo-03.html#v43\" data-v=\"3.43\">3.43</a>): con una imagen guerrera aplicada a un enemigo interior. Allí había que matar el deseo; aquí, cortar la duda. Y con el mismo imperativo que abrió la enseñanza: «levántate» (<em>uttiṣṭha</em>), como en <a class=\"vref\" href=\"capitulo-02.html#v3\" data-v=\"2.3\">2.3</a> y <a class=\"vref\" href=\"capitulo-02.html#v37\" data-v=\"2.37\">2.37</a>.</p><p>La duda está «en el corazón» y nace «de la ignorancia»: no es un problema de información que se resuelva con más argumentos, sino una falta de visión que sólo corta el conocimiento. El remedio, sin embargo, no es quedarse a contemplar: «aférrate al yoga y levántate». El conocimiento desemboca en la acción.</p>", "interp": [{"titulo": "El yoga como medio", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lee «aférrate al yoga» como «recurre al yoga de la acción», el medio que prepara la visión correcta, y «levántate» como la orden de combatir: Arjuna, que todavía no ha alcanzado el conocimiento, debe actuar.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "De la duda a la acción", "html": "<p>El verso cierra el arco abierto en <a class=\"vref\" href=\"capitulo-02.html#v7\" data-v=\"2.7\">2.7</a>, cuando Arjuna confesaba no saber qué era lo mejor. La respuesta no es una nueva regla, sino un conocimiento que disuelve la duda y devuelve la capacidad de actuar. La pregunta de Arjuna no ha terminado —volverá a dudar al comienzo del capítulo 5—, pero la dirección de la enseñanza queda clara: la Gītā no enseña a dejar de actuar, sino a actuar sin duda.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "La espada interior", "html": "<p>Las lecturas alegóricas, como la de <a class=\"t\" href=\"glosario.html#gandhi\" data-t=\"gandhi\">Gandhi</a>, encuentran aquí uno de sus apoyos: la espada de la que habla Kṛṣṇa no es la del guerrero, sino la del conocimiento, y el enemigo está en el corazón. Para ellas toda la batalla de <a class=\"t\" href=\"glosario.html#kuruksetra\" data-t=\"kuruksetra\">Kurukṣetra</a> se desarrolla en ese mismo lugar.</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "cortar-la-duda"}], "ensenanzas": [{"id": "descensos-de-krsna", "desde": 5, "hasta": 8, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Por qué y cómo desciende Kṛṣṇa", "resumen": "<p>Kṛṣṇa ha nacido muchas veces, como todos, pero a diferencia de los demás seres no lo arrastra el karma: no nacido e imperecedero, se manifiesta por su propio poder (<a class=\"t\" href=\"glosario.html#maya\" data-t=\"maya\">māyā</a>), apoyándose en su naturaleza. Lo hace cada vez que el <a class=\"t\" href=\"glosario.html#dharma\" data-t=\"dharma\">dharma</a> decae, para proteger a los buenos, destruir a los malhechores y dar firmeza al orden del mundo. Es el núcleo de la doctrina del <a class=\"t\" href=\"glosario.html#avatara\" data-t=\"avatara\">avatāra</a>.</p>"}, {"id": "nacimiento-y-obra-divinos", "desde": 9, "hasta": 10, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Conocer el nacimiento y la obra divinos", "resumen": "<p>Conocer de verdad que el nacimiento y la obra de Kṛṣṇa son divinos —no producidos por el karma— libra del renacimiento y lleva a él. Así lo alcanzaron muchos: libres de apego, temor e ira, absortos y refugiados en él, purificados por el conocimiento.</p>"}, {"id": "como-se-acercan", "desde": 11, "hasta": 11, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Cada cual es acogido según se acerca", "resumen": "<p>Dios no es parcial: corresponde a cada uno según el modo en que se acerca a él, con la misma raíz, √bhaj, de la que viene <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">bhakti</a>. El verso funda la idea de una reciprocidad entre el hombre y Dios y, en lecturas modernas, la de que todos los caminos religiosos conducen a la misma meta.</p>"}, {"id": "autor-sin-ser-agente", "desde": 13, "hasta": 14, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Autor sin ser agente: la acción que no mancha", "resumen": "<p>Kṛṣṇa ha creado el orden del mundo y sigue actuando, pero no es agente en el sentido que ata: las acciones no lo manchan porque no desea su fruto. Quien lo conoce así queda también libre. Es la enseñanza de <a class=\"vref\" href=\"capitulo-02.html#v47\" data-v=\"2.47\">2.47</a>, obrar sin apego al fruto, mostrada en Dios mismo como modelo.</p>"}, {"id": "inaccion-en-la-accion", "desde": 17, "hasta": 18, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Ver la inacción en la acción", "resumen": "<p>La distinción entre <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a> e <a class=\"t\" href=\"glosario.html#akarma\" data-t=\"akarma\">inacción</a> no coincide con la de moverse o quedarse quieto. Hay que entender la acción, la <a class=\"t\" href=\"glosario.html#vikarma\" data-t=\"vikarma\">acción indebida</a> y la inacción, porque el camino de la acción es profundo; y el que tiene <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> es el que ve la inacción en la acción y la acción en la inacción. Lo que cuenta no es lo que se hace por fuera, sino desde dónde se hace.</p>"}, {"id": "obrar-sin-quedar-atado", "desde": 19, "hasta": 23, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Obrar sin quedar atado", "resumen": "<p>Retrato de quien actúa sin que la acción lo ate, rasgo por rasgo: emprender sin el <a class=\"t\" href=\"glosario.html#kama\" data-t=\"kama\">deseo</a> ni el propósito interesado; abandonar el apego al <a class=\"t\" href=\"glosario.html#phala\" data-t=\"phala\">fruto</a>; no depender de nada, sin esperanzas ni posesiones; contentarse con lo que llega; quedar igual ante el éxito y el fracaso; obrar con vistas al <a class=\"t\" href=\"glosario.html#yajna\" data-t=\"yajna\">sacrificio</a>. Para quien así actúa, el fuego del <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a> quema las acciones y la acción entera «se disuelve».</p>"}, {"id": "ver-brahman-en-la-accion", "desde": 24, "hasta": 24, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Ver brahman en toda acción", "resumen": "<p>Cada elemento de la acción —lo que se ofrece, aquello con que se ofrece, el fuego, el que actúa y la meta— se contempla como <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>. Quien actúa así, absorto en brahman, no queda atado por lo que hace. Es la práctica que se renueva cada día al recitar este verso antes de comer.</p>"}, {"id": "formas-del-sacrificio", "desde": 25, "hasta": 32, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Las muchas formas del sacrificio", "resumen": "<p>Kṛṣṇa extiende el <a class=\"t\" href=\"glosario.html#yajna\" data-t=\"yajna\">sacrificio</a> más allá del rito: dominar los sentidos, recibir sin apego sus objetos, ofrecer los propios bienes, la austeridad, el yoga, el estudio, el <a class=\"t\" href=\"glosario.html#pranayama\" data-t=\"pranayama\">control del aliento</a> y la moderación en el alimento son otras tantas ofrendas. Todas nacen de la acción, y quien lo sabe se libera (<a class=\"vref\" href=\"capitulo-04.html#v32\" data-v=\"4.32\">4.32</a>).</p>"}, {"id": "sacrificio-del-conocimiento", "desde": 33, "hasta": 33, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "El sacrificio del conocimiento", "resumen": "<p>De todos los sacrificios, el del conocimiento es el superior, porque toda acción culmina en él. Las demás ofrendas preparan; el <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a> es su término.</p>"}, {"id": "recibir-el-conocimiento", "desde": 34, "hasta": 34, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Cómo se recibe el conocimiento", "resumen": "<p>El conocimiento se aprende de quienes ven la realidad, no sólo de quienes saben la doctrina, y con tres disposiciones: la reverencia (<em>praṇipāta</em>), la pregunta que va a fondo (<em>paripraśna</em>) y el servicio (<em>sevā</em>). Es la relación tradicional entre maestro y discípulo que describen las <a class=\"t\" href=\"glosario.html#upanisad\" data-t=\"upanisad\">Upaniṣads</a>.</p>"}, {"id": "el-conocimiento-que-purifica", "desde": 35, "hasta": 38, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "El conocimiento que lo purifica todo", "resumen": "<p>El conocimiento disuelve el extravío y hace ver a todos los seres en el sí-mismo y en Kṛṣṇa. Es la barca que atraviesa cualquier mal y el fuego que reduce a cenizas las acciones y sus frutos. Nada purifica como él, y quien se ha preparado por el yoga lo encuentra a su tiempo dentro de sí.</p>"}, {"id": "la-fe-y-la-duda", "desde": 39, "hasta": 40, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "La fe y la duda", "resumen": "<p>Alcanza el conocimiento quien tiene <a class=\"t\" href=\"glosario.html#sraddha\" data-t=\"sraddha\">fe</a>, se entrega a él y domina los sentidos; y con el conocimiento llega pronto la paz suprema. El que no tiene fe y vive en la <a class=\"t\" href=\"glosario.html#samsaya\" data-t=\"samsaya\">duda</a> se pierde: la indecisión le quita este mundo y el otro.</p>"}, {"id": "cortar-la-duda", "desde": 41, "hasta": 42, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Cortar la duda y levantarse", "resumen": "<p>A quien ha renunciado a las acciones por el yoga, ha cortado la duda con el conocimiento y es dueño de sí, las acciones no lo atan. Por eso hay que cortar con la espada del conocimiento la duda nacida de la ignorancia, aferrarse al yoga y levantarse a actuar.</p>"}]};
